-- Enable RLS
alter table public.receipts enable row level security;

-- Helper function to check if current user is service role
create function public.is_service_role()
returns boolean as $$
begin
  return nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role' = 'service_role';
end;
$$ language plpgsql security definer;

-- Policies for public.receipts

-- R5: Service role has full access (bypasses RLS normally, but explicit policy for safety)
create policy "service_role_full_access"
  on public.receipts
  for all
  to service_role
  using (true)
  with check (true);

-- R4: Anonymous cannot read any receipts
create policy "anon_no_select"
  on public.receipts
  for select
  to anon
  using (false);

-- R4: Anonymous cannot insert any receipts
create policy "anon_no_insert"
  on public.receipts
  for insert
  to anon
  with check (false);

-- R4: Anonymous cannot update any receipts
create policy "anon_no_update"
  on public.receipts
  for update
  to anon
  using (false)
  with check (false);

-- R4: Anonymous cannot delete any receipts
create policy "anon_no_delete"
  on public.receipts
  for delete
  to anon
  using (false);

-- R1: Users can read receipts they uploaded (not imported receipts with null uploaded_by)
create policy "authenticated_select_own"
  on public.receipts
  for select
  to authenticated
  using (uploaded_by = auth.uid());

-- R2: Users can add receipts only as themselves
-- R3: Users cannot turn their own receipts into imported ones (handled in update)
create policy "authenticated_insert_own"
  on public.receipts
  for insert
  to authenticated
  with check (uploaded_by = auth.uid());

-- R1: Users can edit receipts they uploaded
-- R3: Users cannot change uploaded_by to null (imported), and can only update their own
create policy "authenticated_update_own"
  on public.receipts
  for update
  to authenticated
  using (uploaded_by = auth.uid())
  with check (uploaded_by = auth.uid());

-- R1: Users can delete receipts they uploaded
create policy "authenticated_delete_own"
  on public.receipts
  for delete
  to authenticated
  using (uploaded_by = auth.uid());

-- Trigger to prevent users from setting uploaded_by to null on insert/update
create function public.prevent_null_uploaded_by_for_users()
returns trigger as $$
begin
  if new.uploaded_by is null and not public.is_service_role() then
    raise exception 'Only server-side code can create imported receipts with null uploaded_by';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger enforce_uploaded_by_not_null_for_users
  before insert or update on public.receipts
  for each row
  execute function public.prevent_null_uploaded_by_for_users();

-- Trigger to prevent users from updating imported receipts (uploaded_by is null)
-- Additional safeguard: prevent claiming imported receipts
create function public.prevent_claiming_imported_receipts()
returns trigger as $$
begin
  -- If old row has null uploaded_by (imported), only service_role can update
  if old.uploaded_by is null and not public.is_service_role() then
    raise exception 'Imported receipts cannot be modified by users';
  end if;
  -- Prevent changing uploaded_by from non-null to null (making it imported)
  if old.uploaded_by is not null and new.uploaded_by is null and not public.is_service_role() then
    raise exception 'Cannot convert user receipt to imported receipt';
  end if;
  -- Prevent changing uploaded_by to a different user (claiming)
  if old.uploaded_by is not null and new.uploaded_by is not null and old.uploaded_by <> new.uploaded_by and not public.is_service_role() then
    raise exception 'Cannot transfer receipt to another user';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger enforce_no_claiming_imported
  before update on public.receipts
  for each row
  execute function public.prevent_claiming_imported_receipts();

-- Revoke public access and grant appropriate permissions
revoke all on public.receipts from anon, authenticated;
grant select, insert, update, delete on public.receipts to authenticated;
grant usage on sequence public.receipts_id_seq to authenticated;

-- Ensure service_role has full access (default in Supabase, but explicit for clarity)
grant all on public.receipts to service_role;
grant all on sequence public.receipts_id_seq to service_role;
