create or replace function public.enforce_receipt_constraints()
returns trigger
language plpgsql
security definer
as $$
begin
  -- R2: Users can only add receipts as themselves
  if TG_OP = 'INSERT' then
    if new.uploaded_by is not null and new.uploaded_by != auth.uid() then
      raise exception 'Users can only upload receipts as themselves';
    end if;
  end if;

  -- R3: Prevent users from claiming imported receipts or turning their receipts into imported ones
  if TG_OP = 'UPDATE' then
    -- Cannot change uploaded_by to null (turn into imported)
    if old.uploaded_by is not null and new.uploaded_by is null then
      raise exception 'Cannot convert personal receipt to imported receipt';
    end if;
    -- Cannot claim an imported receipt (null -> not null)
    if old.uploaded_by is null and new.uploaded_by is not null then
      raise exception 'Cannot claim imported receipts';
    end if;
    -- Cannot change ownership to another user
    if old.uploaded_by is not null and new.uploaded_by is not null and old.uploaded_by != new.uploaded_by then
      raise exception 'Cannot change receipt ownership';
    end if;
  end if;

  return new;
end;
$$;

