-- Helper function to check if current user is an agent
create or replace function public.is_agent(user_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select coalesce(
    (select is_agent from public.profiles where id = user_id),
    false
  );
$$;

-- Helper function to get current user's agent status
create or replace function public.current_user_is_agent()
returns boolean
language sql
security definer
stable
as $$
  select public.is_agent(auth.uid());
$$;

-- Profiles policies
create policy "profiles_select"
  on public.profiles
  for select
  to authenticated
  using (
    id = auth.uid() or public.current_user_is_agent()
  );

create policy "profiles_update_display_name"
  on public.profiles
  for update
  to authenticated
  using (id = auth.uid())
  with check (id = auth.uid() and is_agent = (select is_agent from public.profiles where id = auth.uid()));

-- Tickets policies
create policy "tickets_select"
  on public.tickets
  for select
  to authenticated
  using (
    requester_id = auth.uid() or public.current_user_is_agent()
  );

create policy "tickets_insert"
  on public.tickets
  for insert
  to authenticated
  with check (
    requester_id = auth.uid()
    and status = 'open'
    and assigned_agent is null
  );

create policy "tickets_update_agent_only"
  on public.tickets
  for update
  to authenticated
  using (public.current_user_is_agent())
  with check (public.current_user_is_agent());

create policy "tickets_delete_prevent"
  on public.tickets
  for delete
  to authenticated
  using (false);

-- Prevent any delete on tickets (additional safety)
create policy "tickets_delete_all_prevent"
  on public.tickets
  for delete
  to anon, authenticated
  using (false);

-- Revoke direct access from anon
revoke all on public.profiles from anon;
revoke all on public.tickets from anon;

-- Grant access to authenticated users
grant select, update(display_name) on public.profiles to authenticated;
grant select, insert on public.tickets to authenticated;
grant update on public.tickets to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
