grant all on public.tickets to service_role;

-- Function to prevent is_agent changes via trigger
create or replace function public.prevent_agent_status_change()
returns trigger
language plpgsql
security definer
as $$
begin
  if new.is_agent <> old.is_agent then
    raise exception 'Changing agent status is not allowed';
  end if;
  return new;
end;
$$;

create trigger prevent_agent_status_change_trigger
  before update on public.profiles
  for each row
  execute function public.prevent_agent_status_change();

-- Additional safety: prevent insert of tickets with non-open status or assigned agent via trigger
create or replace function public.enforce_ticket_insert_rules()
returns trigger
language plpgsql
security definer
as $$
begin
  if new.status <> 'open' then
    raise exception 'New tickets must have status open';
  end if;
  if new.assigned_agent is not null then
    raise exception 'New tickets cannot have an assigned agent';
  end if;
  if new.requester_id <> auth.uid() then
    raise exception 'Can only create tickets as yourself';
  end if;
  return new;
end;
$$;

create trigger enforce_ticket_insert_rules_trigger
  before insert on public.tickets
  for each row
  execute function public.enforce_ticket_insert_rules();
