```sql
-- Enable RLS on tables
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

-- Helper function: check if current user is suspended
create or replace function public.is_current_user_suspended()
returns boolean as $$
begin
  return exists (
    select 1 from public.accounts
    where user_id = auth.uid() and suspended = true
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user can read file (owner or valid share)
create or replace function public.can_read_file(file_row public.files)
returns boolean as $$
begin
  -- Check if user is suspended
  if public.is_current_user_suspended() then
    return false;
  end if;

  -- Owner can always read
  if file_row.owner_id = auth.uid() then
    return true;
  end if;

  -- Check for valid share
  return exists (
    select 1 from public.file_shares
    where file_id = file_row.id
      and shared_with = auth.uid()
      and (expires_at is null or expires_at > now())
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user can edit file (owner or valid edit share)
create or replace function public.can_edit_file(file_row public.files)
returns boolean as $$
begin
  -- Check if user is suspended
  if public.is_current_user_suspended() then
    return false;
  end if;

  -- Owner can always edit
  if file_row.owner_id = auth.uid() then
    return true;
  end if;

  -- Check for valid edit share
  return exists (
    select 1 from public.file_shares
    where file_id = file_row.id
      and shared_with = auth.uid()
      and can_edit = true
      and (expires_at is null or expires_at > now())
  );
end;
$$ language plpgsql security definer;

-- ACCOUNTS policies
create policy "accounts_select_own"
  on public.accounts
  for select
  to authenticated
  using (user_id = auth.uid() and not suspended);

create policy "accounts_service_all"
  on public.accounts
  for all
  to service_role
  using (true)
  with check (true);

-- FILES policies
create policy "files_select_accessible"
  on public.files
  for select
  to authenticated
