-- Helper function: check if user is manager of a department
create or replace function public.is_department_manager(p_user_id uuid, p_department_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.department_members
    where user_id = p_user_id
      and department_id = p_department_id
      and is_manager = true
  );
$$;

-- Helper function: check if user belongs to a department
create or replace function public.is_department_member(p_user_id uuid, p_department_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.department_members
    where user_id = p_user_id
      and department_id = p_department_id
  );
$$;

-- R4, R5: decide_expense function
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
as $$
declare
  v_expense record;
  v_caller_role text;
  v_caller_id uuid;
begin
  -- Get caller info from JWT
  v_caller_role := coalesce(auth.jwt() ->> 'role', 'authenticated');
  v_caller_id := auth.uid();

  -- Fetch the expense
  select * into v_expense from public.expenses where id = p_expense_id;

  if v_expense is null then
    raise exception 'Expense not found';
  end if;

  -- Service role bypass (R5)
  if v_caller_role = 'service_role' then
    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending';
    end if;

    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = null
    where id = p_expense_id;

    return;
  end if;

  -- Regular authenticated user checks (R4)
  -- Must be manager of the expense's department
  if not public.is_department_manager(v_caller_id, v_expense.department_id) then
    raise exception 'Caller is not a manager of this department';
  end if;

  -- Expense must be pending
  if v_expense.status != 'pending' then
    raise exception 'Expense is not pending';
  end if;

  -- Caller must not be the submitter
  if v_expense.submitted_by = v_caller_id then
    raise exception 'Manager cannot decide their own expense';
  end if;

  -- All checks passed, update the expense
  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = v_caller_id
  where id = p_expense_id;
end;
$$;

