create policy "department_members_service_all"
  on public.department_members
  for all
  to service_role
  using (true)
  with check (true);

-- Expenses policies

-- R1: Users can read their own expenses, managers can read all expenses in their departments
create policy "expenses_select"
  on public.expenses
  for select
  to authenticated
  using (
    submitted_by = auth.uid()
    or public.is_department_manager(auth.uid(), department_id)
  );

-- R2: Users can submit expenses only as themselves, only to their departments, pending, no decision
create policy "expenses_insert"
  on public.expenses
  for insert
  to authenticated
  with check (
    submitted_by = auth.uid()
    and public.is_department_member(auth.uid(), department_id)
    and status = 'pending'
    and decided_by is null
  );

-- R3: Submitters can change amount of their own pending expenses only
-- Nobody can change status or decided_by directly
create policy "expenses_update"
  on public.expenses
  for update
  to authenticated
  using (
    submitted_by = auth.uid()
    and status = 'pending'
  )
  with check (
    submitted_by = auth.uid()
    and status = 'pending'
    -- status and decided_by cannot be changed via direct update
    -- This is enforced by not allowing those columns in UPDATE
  );

-- R6: Expenses cannot be deleted through the app
-- No delete policy for authenticated

-- R8: Service role full access
create policy "expenses_service_all"
  on public.expenses
  for all
  to service_role
  using (true)
  with check (true);

-- Prevent direct update of status and decided_by columns via trigger
create or replace function public.prevent_status_decided_by_update()
returns trigger
language plpgsql
security definer
as $$
begin
  if OLD.status is distinct from NEW.status then
    raise exception 'Cannot update status directly. Use decide_expense() instead.';
  end if;
  if OLD.decided_by is distinct from NEW.decided_by then
    raise exception 'Cannot update decided_by directly. Use decide_expense() instead.';
  end if;
  return NEW;
end;
$$;

create trigger prevent_status_decided_by_update_trigger
  before update on public.expenses
  for each row
  execute function public.prevent_status_decided_by_update();

