create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
as $$
declare
  v_expense record;
  v_caller_role text;
  v_is_service_role boolean;
begin
  -- Determine if called by service_role
  v_caller_role := coalesce(auth.role(), 'anon');
  v_is_service_role := (v_caller_role = 'service_role');

  -- Get the expense
  select * into v_expense from public.expenses where id = p_expense_id;

  if not found then
    raise exception 'Expense not found.';
  end if;

  -- Service role can approve any pending expense, decided_by left empty
  if v_is_service_role then
    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending.';
    end if;

    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = null
    where id = p_expense_id;

    return;
  end if;

  -- Regular authenticated user checks
  if v_caller_role != 'authenticated' then
    raise exception 'Only authenticated users can decide expenses.';
  end if;

  -- Check: caller manages the expense's department
  if not public.is_department_manager(auth.uid(), v_expense.department_id) then
    raise exception 'You do not manage this department.';
  end if;

  -- Check: expense is pending
  if v_expense.status != 'pending' then
    raise exception 'Expense is not pending.';
  end if;

  -- Check: caller did not submit the expense
  if v_expense.submitted_by = auth.uid() then
    raise exception 'You cannot decide your own expense.';
  end if;

  -- All checks passed, update the expense
  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = auth.uid()
  where id = p_expense_id;
end;
$$;

