create policy "expenses_select"
  on public.expenses
  for select
  to authenticated
  using (
    submitted_by = auth.uid()
    or public.is_department_manager(auth.uid(), department_id)
  );

-- R2: Users can submit expenses only as themselves, only to departments they belong to,
-- with status pending and no decision recorded
create policy "expenses_insert"
  on public.expenses
  for insert
  to authenticated
  with check (
    submitted_by = auth.uid()
    and public.is_department_member(auth.uid(), department_id)
    and status = 'pending'
    and decided_by is null
  );

-- R3: Submitters can change amount of their own pending expenses
-- Nobody can change status or decided_by directly (enforced by columns not in update)
create policy "expenses_update"
  on public.expenses
  for update
  to authenticated
  using (
    submitted_by = auth.uid()
    and status = 'pending'
  )
  with check (
    submitted_by = auth.uid()
    and status = 'pending'
  );

-- R6: Expenses cannot be deleted
-- No delete policy = delete denied for all roles except service_role (bypasses RLS)

-- R6: Departments and memberships cannot be changed through the app
-- No update/insert/delete policies on departments and department_members
-- (except select policies above)

-- R7: Anonymous visitors cannot see anything or decide expenses
-- No policies for anon role = denied (except where explicitly granted)

-- R8: Service role has full access (bypasses RLS automatically)

-- Ensure service_role can use the function (already security definer, but be explicit)
grant execute on function public.decide_expense(bigint, boolean) to service_role;
grant execute on function public.decide_expense(bigint, boolean) to authenticated;

-- Revoke dangerous defaults
revoke all on public.departments from anon;
revoke all on public.department_members from anon;
revoke all on public.expenses from anon;

revoke insert, update, delete on public.departments from authenticated;
revoke insert, update, delete on public.department_members from authenticated;
revoke delete on public.expenses from authenticated;

-- Grant necessary permissions
grant select on public.departments to authenticated;
grant select on public.department_members to authenticated;
grant select, insert, update on public.expenses to authenticated;

-- Grant usage on helper functions
grant execute on function public.is_department_manager(uuid, bigint) to authenticated;
grant execute on function public.is_department_member(uuid, bigint) to authenticated;
