-- Helper function: check if user is a member of an org with at least a given role
create or replace function public.is_org_member(org_id bigint, user_id uuid, min_role text default 'member')
returns boolean as $$
declare
  user_role text;
  role_hierarchy int;
  min_role_hierarchy int;
begin
  select case role
    when 'owner' then 3
    when 'admin' then 2
    when 'member' then 1
  end into role_hierarchy
  from public.org_members
  where org_members.org_id = is_org_member.org_id
    and org_members.user_id = is_org_member.user_id;

  min_role_hierarchy := case min_role
    when 'owner' then 3
    when 'admin' then 2
    when 'member' then 1
  end;

  return coalesce(role_hierarchy, 0) >= min_role_hierarchy;
end;
$$ language plpgsql security definer;

