create policy "invoices_update"
  on public.invoices
  for update
  to authenticated
  using (
    public.is_service_role()
    or (
      -- Creator updating draft: can change customer, amount, status draft->sent
      created_by = auth.uid()
      and status = 'draft'
    )
    or (
      -- Finance staff updating sent: can change status to paid or void
      public.is_finance_staff()
      and status = 'sent'
    )
  )
  with check (
    public.is_service_role()
    or (
      -- Creator updating draft: must remain draft or become sent, customer/amount can change
      created_by = auth.uid()
      and (
        -- If it was draft, can stay draft or become sent
        status in ('draft', 'sent')
      )
      -- But we need to check the transition more carefully via trigger
    )
