-- Trigger function to enforce update rules
create or replace function public.invoices_update_check()
returns trigger as $$
begin
  -- R6: Nobody can change created_by
  if NEW.created_by IS DISTINCT FROM OLD.created_by then
    raise exception 'Cannot change invoice creator';
  end if;

  -- Service role bypasses status rules
  if public.is_service_role() then
    return NEW;
  end if;

  -- Creator of draft can change customer, amount, and status from draft to sent
  if OLD.status = 'draft' and OLD.created_by = auth.uid() then
    if NEW.status not in ('draft', 'sent') then
      raise exception 'Draft invoice can only be changed to sent status';
    end if;
    return NEW;
  end if;

  -- Finance staff can change sent to paid or void
  if OLD.status = 'sent' and public.is_finance_staff() then
    if NEW.status not in ('paid', 'void') then
      raise exception 'Sent invoice can only be changed to paid or void';
    end if;
    -- Finance staff can only change status, not customer or amount
    if NEW.customer IS DISTINCT FROM OLD.customer or NEW.amount IS DISTINCT FROM OLD.amount then
      raise exception 'Finance staff can only change invoice status';
    end if;
    return NEW;
  end if;

  -- No other changes allowed
  raise exception 'Invoice update not allowed';
end;
$$ language plpgsql security definer;

create trigger invoices_update_trigger
  before update on public.invoices
  for each row
  execute function public.invoices_update_check();

-- Trigger function to enforce insert rules
create or replace function public.invoices_insert_check()
returns trigger as $$
begin
  -- Service role bypasses
  if public.is_service_role() then
    return NEW;
  end if;

  -- Must be created by current user as draft
  if NEW.created_by != auth.uid() then
    raise exception 'Invoice must be created by current user';
  end if;

  if NEW.status != 'draft' then
    raise exception 'New invoice must be draft';
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

create trigger invoices_insert_trigger
  before insert on public.invoices
  for each row
  execute function public.invoices_insert_check();

