```sql
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.enrollments enable row level security;

-- Helper function to check if user is instructor of a course
create or replace function public.is_course_instructor(course_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.courses c
    where c.id = course_id and c.instructor_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if user is enrolled in a course
create or replace function public.is_enrolled(course_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.enrollments e
    where e.course_id = course_id and e.student_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Courses policies
create policy "courses_select"
  on public.courses
  for select
  using (
    is_published = true
    or instructor_id = auth.uid()
  );

create policy "courses_insert"
  on public.courses
  for insert
  with check (
    auth.role() = 'authenticated'
    and instructor_id = auth.uid()
  );

create policy "courses_update"
  on public.courses
  for update
  using (instructor_id = auth.uid())
  with check (instructor_id = auth.uid());

create policy "courses_delete"
  on public.courses
  for delete
  using (instructor_id = auth.uid());

-- Lessons policies
create policy "lessons_select"
  on public.lessons
  for select
  using (
    exists (
      select 1 from public.courses c
      where c.id = lessons.course_id
      and (
        -- preview lessons of published courses
        (c.is_published = true and lessons.is_preview = true)
        -- enrolled students can read all lessons of published courses
        or (c.is_published = true and public.is_enrolled(c.id))
        -- instructors can read all their course lessons
        or c.instructor_id = auth.uid()
      )
    )
  );

create policy "lessons_insert"
  on public.lessons
  for insert
  with check (public.is_course_instructor(course_id));

create policy "lessons_update"
  on public.lessons
  for update
  using (public.is_course_instructor(course_id))
  with check (public.is_course_instructor(course_id));

create policy "lessons_delete"
  on public.lessons
  for delete
  using (public.is_course_instructor(course_id));

-- Enrollments policies
create policy "enrollments_select"
  on public.enrollments
  for select
  using (
    student_id = auth.uid()
    or public.is_course_instructor(course_id)
  );

create policy "enrollments_insert"
  on public.enrollments
  for insert
  with check (
    auth.role() = 'authenticated'
    and student_id = auth.uid()
    and exists (
      select 1 from public.courses c
      where c.id = course_id and c.is_published = true
    )
  );

create policy "enrollments_delete"
  on public.enrollments
  for delete
  using (student_id = auth.uid());

-- Prevent updates on enrollments (only insert/delete allowed)
create policy "enrollments_update"
  on public.enrollments
  for update
  using (false);

-- Revoke all from anon and authenticated, then grant specific access
revoke all on public.courses from anon, authenticated;
revoke all on public.lessons from anon, authenticated;
revoke all on public.enrollments from anon, authenticated;

grant select on public.courses to anon, authenticated;
grant insert, update, delete on public.courses to authenticated;

grant select on public.lessons to anon, authenticated;
grant insert, update, delete on public.lessons to authenticated;

grant select on public.enrollments to anon, authenticated;
grant insert, delete on public.enrollments to authenticated;

-- Grant usage on helper functions
grant execute on function public.is_course_instructor(bigint) to anon, authenticated;
grant execute on function public.is_enrolled(bigint) to anon, authenticated;
