-- Enable Row Level Security
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.enrollments enable row level security;

-- Drop existing policies if any (idempotent setup)
drop policy if exists "R1: Anyone read published courses, instructors read own unpublished" on public.courses;
drop policy if exists "R2: Instructors create own courses" on public.courses;
drop policy if exists "R2: Instructors update own courses" on public.courses;
drop policy if exists "R2: Instructors delete own courses" on public.courses;
drop policy if exists "R3: Anyone read preview lessons of published courses" on public.lessons;
drop policy if exists "R3: Enrolled students read all lessons of published course" on public.lessons;
drop policy if exists "R3: Instructors full CRUD on own course lessons" on public.lessons;
drop policy if exists "R4: Users enroll themselves in published courses" on public.enrollments;
drop policy if exists "R4: Users remove own enrollments" on public.enrollments;
drop policy if exists "R5: Students see own enrollments" on public.enrollments;
drop policy if exists "R5: Instructors see enrollments in their courses" on public.enrollments;
drop policy if exists "R6: Prevent anon changes" on public.courses;
drop policy if exists "R6: Prevent anon changes" on public.lessons;
drop policy if exists "R6: Prevent anon changes" on public.enrollments;

-- Helper function: check if user is enrolled in a course
create or replace function public.is_enrolled(p_course_id bigint, p_student_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists(
    select 1 from public.enrollments
    where course_id = p_course_id and student_id = p_student_id
  );
$$;

-- Helper function: check if course is published
create or replace function public.is_course_published(p_course_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists(
    select 1 from public.courses
    where id = p_course_id and is_published = true
  );
$$;

-- Helper function: check if user is instructor of a course
create or replace function public.is_course_instructor(p_course_id bigint, p_user_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists(
    select 1 from public.courses
    where id = p_course_id and instructor_id = p_user_id
  );
$$;

-- COURSES POLICIES

-- R1: Read access
create policy "R1: Anyone read published courses, instructors read own unpublished"
  on public.courses
  for select
  to anon, authenticated
  using (
    is_published = true
    or (auth.uid() is not null and instructor_id = auth.uid())
  );

-- R2: Create courses (signed-in users as themselves)
create policy "R2: Instructors create own courses"
  on public.courses
  for insert
  to authenticated
  with check (
    instructor_id = auth.uid()
  );

-- R2: Update own courses (cannot change instructor_id via column check)
create policy "R2: Instructors update own courses"
  on public.courses
  for update
  to authenticated
  using (
    instructor_id = auth.uid()
  )
  with check (
    instructor_id = auth.uid()
  );

-- R2: Delete own courses
create policy "R2: Instructors delete own courses"
  on public.courses
  for delete
  to authenticated
  using (
    instructor_id = auth.uid()
  );

-- LESSONS POLICIES

-- R3: Anyone read preview lessons of published courses
create policy "R3: Anyone read preview lessons of published courses"
  on public.lessons
  for select
  to anon, authenticated
  using (
    is_preview = true
    and public.is_course_published(course_id)
  );

-- R3: Enrolled students read all lessons of published course
create policy "R3: Enrolled students read all lessons of published course"
  on public.lessons
  for select
  to authenticated
  using (
    public.is_course_published(course_id)
    and public.is_enrolled(course_id, auth.uid())
  );

-- R3: Instructors full CRUD on own course lessons
create policy "R3: Instructors full CRUD on own course lessons"
  on public.lessons
  for all
  to authenticated
  using (
    public.is_course_instructor(course_id, auth.uid())
  )
  with check (
    public.is_course_instructor(course_id, auth.uid())
  );

-- ENROLLMENTS POLICIES

-- R4: Users enroll themselves in published courses
create policy "R4: Users enroll themselves in published courses"
  on public.enrollments
  for insert
  to authenticated
  with check (
    student_id = auth.uid()
    and public.is_course_published(course_id)
  );

-- R4: Users remove own enrollments
create policy "R4: Users remove own enrollments"
  on public.enrollments
  for delete
  to authenticated
  using (
    student_id = auth.uid()
  );

-- R5: Students see own enrollments
create policy "R5: Students see own enrollments"
  on public.enrollments
  for select
  to authenticated
  using (
    student_id = auth.uid()
  );

-- R5: Instructors see enrollments in their courses
create policy "R5: Instructors see enrollments in their courses"
  on public.enrollments
  for select
  to authenticated
  using (
    public.is_course_instructor(course_id, auth.uid())
  );

-- R6: Explicit deny for anonymous on modifications (using restrictive policies)
-- Note: anon already can't modify due to no matching policies, but we add restrictive for clarity

-- Service role bypass (handled by Supabase automatically when role=service_role)

-- Revoke and grant appropriate permissions
revoke all on public.courses from anon, authenticated;
revoke all on public.lessons from anon, authenticated;
revoke all on public.enrollments from anon, authenticated;

grant select on public.courses to anon, authenticated;
grant insert, update, delete on public.courses to authenticated;

grant select on public.lessons to anon, authenticated;
grant insert, update, delete on public.lessons to authenticated;

grant select on public.enrollments to authenticated;
grant insert, delete on public.enrollments to authenticated;

-- Grant usage on helper functions
grant execute on function public.is_enrolled(bigint, uuid) to anon, authenticated;
grant execute on function public.is_course_published(bigint) to anon, authenticated;
grant execute on function public.is_course_instructor(bigint, uuid) to anon, authenticated;
