-- Enable RLS on tables
alter table public.contacts enable row level security;
alter table public.tenant_settings enable row level security;

-- Helper function to get current user's tenant_id from JWT app_metadata
create or replace function public.current_tenant_id()
returns text
language sql
stable
security definer
as $$
  select nullif((auth.jwt() -> 'app_metadata' ->> 'tenant_id'), '');
$$;

-- Helper function to get current user's tenant_role from JWT app_metadata
create or replace function public.current_tenant_role()
returns text
language sql
stable
security definer
as $$
  select nullif((auth.jwt() -> 'app_metadata' ->> 'tenant_role'), '');
$$;

-- Helper function to check if current user is admin of their tenant
create or replace function public.is_tenant_admin()
returns boolean
language sql
stable
security definer
as $$
  select public.current_tenant_role() = 'admin';
$$;

-- Helper function to check if current user belongs to a tenant
create or replace function public.has_tenant()
returns boolean
language sql
stable
security definer
as $$
  select public.current_tenant_id() is not null;
$$;

-- Contacts policies

-- R2, R6: Read contacts (non-archived for all, archived for admins only)
create policy "contacts_select"
  on public.contacts
  for select
  to authenticated
  using (
    public.has_tenant()
    and tenant_id = public.current_tenant_id()
    and (
      not is_archived
      or public.is_tenant_admin()
    )
  );

-- R3, R6: Create contacts in own tenant, as owner, not archived
create policy "contacts_insert"
  on public.contacts
  for insert
  to authenticated
  with check (
    public.has_tenant()
    and tenant_id = public.current_tenant_id()
    and owner_id = auth.uid()
    and is_archived = false
  );

-- R3, R4, R6: Update contacts (owners and admins, cannot change tenant)
create policy "contacts_update"
  on public.contacts
  for update
  to authenticated
  using (
    public.has_tenant()
    and tenant_id = public.current_tenant_id()
    and (
      owner_id = auth.uid()
      or public.is_tenant_admin()
    )
  )
  with check (
    public.has_tenant()
    and tenant_id = public.current_tenant_id()
    and (
      -- Non-admins cannot archive/unarchive
      (not public.is_tenant_admin() and is_archived = (select is_archived from public.contacts where id = contacts.id))
      or public.is_tenant_admin()
    )
  );

-- R4, R6: Delete contacts (admins only)
create policy "contacts_delete"
  on public.contacts
  for delete
  to authenticated
  using (
