create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_from uuid;
  v_from_balance integer;
  v_to_exists boolean;
  v_transfer_id bigint;
begin
  v_from := auth.uid();

  if v_from is null then
    raise exception 'Caller is not signed in';
  end if;

  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  if p_to = v_from then
    raise exception 'Cannot send points to yourself';
  end if;

  select balance into v_from_balance
  from public.wallets
  where user_id = v_from
  for update;

  if v_from_balance is null then
    raise exception 'Caller has no wallet';
  end if;

  if v_from_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  select exists(select 1 from public.wallets where user_id = p_to)
  into v_to_exists;

  if not v_to_exists then
    raise exception 'Recipient has no wallet';
  end if;

  update public.wallets
  set balance = balance - p_amount
  where user_id = v_from;

  update public.wallets
  set balance = balance + p_amount
  where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount)
  values (v_from, p_to, p_amount)
  returning id into v_transfer_id;

  return v_transfer_id;
end;
$$;

