-- Trigger to enforce loan updates only set returned_on
create or replace function public.enforce_loan_return_update()
returns trigger as $$
begin
  -- Only allow returned_on to change from null to a value
  -- Reject if any other column is changed
  if old.id is distinct from new.id or
     old.book_id is distinct from new.book_id or
     old.borrower_id is distinct from new.borrower_id or
     old.borrowed_on is distinct from new.borrowed_on then
    raise exception 'Only returned_on can be updated on a loan';
  end if;

  -- Ensure returned_on is being set (not cleared)
  if old.returned_on is not null then
    raise exception 'Cannot modify a returned loan';
  end if;

  if new.returned_on is null then
    raise exception 'returned_on must be set when returning a loan';
  end if;

  return new;
end;
$$ language plpgsql security definer;

