grant all on public.push_tokens to service_role;
grant usage on sequence public.push_tokens_token_seq to service_role;
grant execute on function public.check_token_ownership to service_role;

-- Explicitly revoke from anon to ensure no access
revoke all on public.push_tokens from anon;
revoke all on public.push_tokens from authenticated;

-- Re-grant necessary privileges to authenticated
grant select, insert, update, delete on public.push_tokens to authenticated;
grant execute on function public.check_token_ownership to authenticated;
