```sql
-- Enable RLS on tables
alter table public.app_config enable row level security;
alter table public.user_flag_overrides enable row level security;

-- Helper function to check if current user is service role
create or replace function public.is_service_role()
returns boolean as $$
begin
  return coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '') = 'service_role';
end;
$$ language plpgsql security definer;

-- Helper function to get effective user_id from request
create or replace function public.requesting_user_id()
returns uuid as $$
begin
  return coalesce(
    current_setting('request.jwt.claims', true)::jsonb->>'sub',
    auth.uid()::text
  )::uuid;
exception
  when others then return null;
end;
$$ language plpgsql stable;

-- app_config policies

-- R1: Anyone can read public config entries
-- R6: Service role can read all
create policy "app_config_select"
  on public.app_config
  for select
  to anon, authenticated
  using (
    is_public = true
    or public.is_service_role()
  );

-- R2: Nobody can modify app_config through the app (only service_role)
create policy "app_config_insert"
  on public.app_config
  for insert
  to authenticated
  with check (public.is_service_role());

create policy "app_config_update"
  on public.app_config
  for update
  to authenticated
  using (public.is_service_role())
  with check (public.is_service_role());

create policy "app_config_delete"
  on public.app_config
  for delete
  to authenticated
  using (public.is_service_role());

-- user_flag_overrides policies

-- R3: Signed-in users can read only their own overrides
-- R5: Anonymous cannot read overrides (no anon policy)
-- R6: Service role can read all
create policy "user_flag_overrides_select"
  on public.user_flag_overrides
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or public.is_service_role()
  );

-- R4: Signed-in users can create their own overrides for public and user_overridable keys
-- R6: Service role can insert all
create policy "user_flag_overrides_insert"
  on public.user_flag_overrides
  for insert
  to authenticated
  with check (
    public.is_service_role()
    or (
      user_id = auth.uid()
      and exists (
        select 1 from public.app_config
        where app_config.key = user_flag_overrides.key
        and app_config.is_public = true
        and app_config.user_overridable = true
      )
    )
  );

-- R4: Signed-in users can update their own overrides for public and user_overridable keys
-- R6: Service role can update all
create policy "user_flag_overrides_update"
  on public.user_flag_overrides
  for update
  to authenticated
  using (
    public.is_service_role()
    or (
      user_id = auth.uid()
      and exists (
        select 1 from public.app_config
        where app_config.key = user_flag_overrides.key
        and app_config.is_public = true
        and app_config.user_overridable = true
      )
    )
  )
  with check (
    public.is_service_role()
    or (
      user_id = auth.uid()
      and exists (
        select 1 from public.app_config
        where app_config.key = user_flag_overrides.key
        and app_config.is_public = true
        and app_config.user_overridable = true
      )
    )
  );

-- R4: Signed-in users can delete their own overrides
-- R6: Service role can delete all
create policy "user_flag_overrides_delete"
  on public.user_flag_overrides
  for delete
  to authenticated
  using (
    user_id = auth.uid()
    or public.is_service_role()
  );

-- Ensure service_role bypass works (belt and suspenders)
create policy "app_config_service_all"
  on public.app_config
  for all
  to service_role
  using (true)
  with check (true);

create policy "user_flag_overrides_service_all"
  on public.user_flag_overrides
  for all
  to service_role
  using (true)
  with check (true);

-- Revoke direct table access from public, grant through API roles
revoke all on public.app_config from public, anon, authenticated;
revoke all on public.user_flag_overrides from public, anon, authenticated;

grant select on public.app_config to anon, authenticated;
grant all on public.user_flag_overrides to authenticated;

-- Grant service_role full access
grant all on public.app_config to service_role;
grant all on public.user_flag_overrides to service_role;

-- Grant execute on helper functions
grant execute on function public.is_service_role() to anon, authenticated, service_role;
grant execute on function public.requesting_user_id() to anon, authenticated, service_role;
