  return exists (
    select 1 from public.employees
    where user_id = employee_uuid
    and manager_id = auth.uid()
  );
end;
$$;

-- Helper function: get current user's manager_id
create or replace function public.get_my_manager()
returns uuid
language plpgsql
security definer
as $$
declare
  mgr_id uuid;
begin
  select manager_id into mgr_id from public.employees where user_id = auth.uid();
  return mgr_id;
end;
$$;

-- EMPLOYEES TABLE POLICIES

-- R6: Signed-in users can read employee directory
create policy "employees_select_authenticated"
  on public.employees
  for select
  to authenticated
  using (true);

-- R6: Nobody can change employees through the app (only service_role bypasses)
-- No insert/update/delete policies for authenticated/anon

-- R7: Anonymous cannot see or change anything (no policies for anon)

-- LEAVE_REQUESTS TABLE POLICIES

-- R1: Employees read own requests, managers read direct reports' requests
create policy "leave_requests_select"
  on public.leave_requests
  for select
  to authenticated
  using (
    employee_id = auth.uid()
    or public.is_manager_of(employee_id)
  );

-- R2: Employees create requests for themselves only, pending with no decided_by
create policy "leave_requests_insert"
  on public.leave_requests
  for insert
  to authenticated
  with check (
    employee_id = auth.uid()
    and status = 'pending'
    and decided_by is null
  );

-- R3, R4, R5: Update policy with validation via trigger
create policy "leave_requests_update"
  on public.leave_requests
  for update
  to authenticated
  using (
    -- Can only update if still pending (R5)
    status = 'pending'
    and (
      -- Employee can update their own pending request (R3)
      employee_id = auth.uid()
      -- Manager can update their direct report's pending request (R4)
      or public.is_manager_of(employee_id)
    )
  );

-- R5: No deletes ever
-- No delete policy

-- Trigger to enforce update field-level rules
create or replace function public.enforce_leave_request_update()
returns trigger
language plpgsql
security definer
as $$
begin
  -- R5: Once not pending, cannot change (defense in depth)
  if old.status != 'pending' then
    raise exception 'Cannot modify leave request that is not pending';
  end if;

  -- If employee is updating their own request
  if old.employee_id = auth.uid() then
    -- R3: Employee cannot approve/reject their own request
    if new.status not in ('pending', 'cancelled') then
      raise exception 'Employees can only cancel their own requests, not approve or reject';
    end if;
    -- R3: Employee can change dates, note, or cancel; cannot set decided_by
    if new.decided_by is not null then
      raise exception 'Employees cannot set decided_by';
    end if;
    -- Allow dates and note changes, status to cancelled
    return new;
  end if;

  -- If manager is updating their direct report's request
  if public.is_manager_of(old.employee_id) then
    -- R4: Manager can only approve or reject (change status and set decided_by)
    -- R4: Manager cannot change dates or note
    if new.starts_on != old.starts_on or new.ends_on != old.ends_on or new.note is distinct from old.note then
      raise exception 'Managers cannot change dates or note when deciding';
    end if;
    -- R4: Manager must set decided_by to themselves
    if new.decided_by != auth.uid() then
      raise exception 'Manager must record themselves as decided_by';
    end if;
    -- R4: Manager can only set status to approved or rejected
    if new.status not in ('approved', 'rejected') then
      raise exception 'Managers can only approve or reject requests';
    end if;
    return new;
  end if;

  raise exception 'Unauthorized update';
end;
$$;

create trigger leave_request_update_trigger
  before update on public.leave_requests
  for each row
  execute function public.enforce_leave_request_update();

-- Revoke default public permissions and grant minimal needed
revoke all on public.employees from anon, authenticated;
revoke all on public.leave_requests from anon, authenticated;

grant select on public.employees to authenticated;
grant select, insert, update on public.leave_requests to authenticated;

grant usage on schema public to anon, authenticated;
grant execute on function public.is_manager_of to authenticated;
grant execute on function public.get_my_manager to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
grant all on public.employees to service_role;
grant all on public.leave_requests to service_role;
grant execute on function public.is_manager_of to service_role;
