  return auth.uid() = employee_uuid;
end;
$$;

-- Helper function: get manager_id for current user
create or replace function public.get_my_manager_id()
returns uuid
language plpgsql
security definer
as $$
declare
  mgr_id uuid;
begin
  select manager_id into mgr_id from public.employees where user_id = auth.uid();
  return mgr_id;
end;
$$;

-- ============================================
-- EMPLOYEES TABLE POLICIES
-- ============================================

-- R6: Signed-in users can read employee directory
create policy employees_select_authenticated
  on public.employees
  for select
  to authenticated
  using (true);

-- R6: Nobody can change employees through the app (no insert/update/delete for authenticated)
-- R7: Anonymous cannot see or change anything (no policies for anon)
-- R8: service_role bypasses RLS

-- ============================================
-- LEAVE_REQUESTS TABLE POLICIES
-- ============================================

-- R1: Employees read own requests; managers read direct reports' requests
create policy leave_requests_select
  on public.leave_requests
  for select
  to authenticated
  using (
    public.is_self(employee_id)
    or public.is_manager_of(employee_id)
  );

-- R2: Employees create requests for themselves only, pending with no decided_by
create policy leave_requests_insert
  on public.leave_requests
  for insert
  to authenticated
  with check (
    public.is_self(employee_id)
    and status = 'pending'
    and decided_by is null
  );

-- R3: While pending, employee can change dates, note, or cancel (status 'cancelled')
-- R4: Manager can approve/reject pending request, recording decided_by
-- R5: Once not pending, nobody can change
create policy leave_requests_update
  on public.leave_requests
  for update
  to authenticated
  using (
    -- Can only update if still pending
    status = 'pending'
  )
  with check (
    -- Must still be pending after update (except cancellation which sets to cancelled, but that's handled by the check constraint and the with check ensures it's one of valid states)
    status in ('pending', 'approved', 'rejected', 'cancelled')
    -- R5: enforced by using clause (only pending rows can be updated)
    -- Additional checks in trigger
  );

-- R5: No delete policy (requests are never deleted)

-- ============================================
-- TRIGGER FOR UPDATE VALIDATION (R3, R4, R5)
-- ============================================

create or replace function public.leave_requests_update_check()
returns trigger
language plpgsql
security definer
as $$
begin
  -- R5: Double-check it's still pending (should be caught by policy, but defense in depth)
  if old.status != 'pending' then
    raise exception 'Cannot modify a leave request that is not pending';
  end if;

  -- R3: Employee updating their own request
  if public.is_self(old.employee_id) then
    -- Employee can only change dates, note, or status to 'cancelled'
    -- Cannot change status to approved or rejected
    if new.status = 'approved' or new.status = 'rejected' then
      raise exception 'Employees cannot approve or reject their own requests';
    end if;
    -- Employee can set status to cancelled or keep pending
    if new.status not in ('pending', 'cancelled') then
      raise exception 'Employees can only cancel or keep pending their own requests';
    end if;
    -- Employee cannot change decided_by
    if new.decided_by is not null then
      raise exception 'Employees cannot set decided_by';
    end if;
    -- Employee cannot change employee_id
    if new.employee_id != old.employee_id then
      raise exception 'Cannot change employee_id';
    end if;
    return new;
  end if;

  -- R4: Manager updating their report's request
  if public.is_manager_of(old.employee_id) then
    -- Manager can only approve or reject (change status and decided_by)
    -- Manager cannot change dates or note
    if new.starts_on != old.starts_on or new.ends_on != old.ends_on or new.note is distinct from old.note then
      raise exception 'Managers cannot change dates or note when deciding';
    end if;
    -- Manager cannot change employee_id
    if new.employee_id != old.employee_id then
      raise exception 'Cannot change employee_id';
    end if;
    -- Manager must set status to approved or rejected
    if new.status not in ('approved', 'rejected') then
      raise exception 'Managers can only approve or reject requests';
    end if;
    -- Manager must set themselves as decided_by
    if new.decided_by != auth.uid() then
      raise exception 'Manager must set themselves as decided_by';
    end if;
    return new;
  end if;

  -- Neither employee nor manager: deny
  raise exception 'Not authorized to update this leave request';
end;
$$;

create trigger leave_requests_update_trigger
  before update on public.leave_requests
  for each row
  execute function public.leave_requests_update_check();

