  on public.leave_requests
  for insert
  to authenticated
  with check (
    employee_id = auth.uid()
    and status = 'pending'
    and decided_by is null
  );

-- R3, R4, R5: Combined update policy with status-based logic
create policy leave_requests_update
  on public.leave_requests
  for update
  to authenticated
  using (
    -- Can only update if: own pending request, or managing a pending request
    (
      employee_id = auth.uid()
      and status = 'pending'
    )
    or (
      public.is_manager_of(employee_id)
      and status = 'pending'
    )
  )
  with check (
    -- After update, validate based on who is updating
    case
      -- Employee updating: must stay pending or become cancelled, can't set decided_by, can't change dates/note if cancelling (actually can change dates/note while pending)
      when employee_id = auth.uid() then
        -- Employee can only update their own pending requests
        -- Status must be 'pending' or 'cancelled'
        status in ('pending', 'cancelled')
        -- If they set cancelled, decided_by must remain null
        and (status != 'cancelled' or decided_by is null)
        -- Cannot approve or reject their own
        and status not in ('approved', 'rejected')

      -- Manager updating: can only approve/reject, must set decided_by to self, can't change dates/note
      when public.is_manager_of(employee_id) then
        status in ('approved', 'rejected')
        and decided_by = auth.uid()

      else false
    end
