  if old.employee_id = auth.uid() then
    -- R3: Employees can change dates, note, or cancel; cannot approve/reject
    if new.status in ('approved', 'rejected') then
      raise exception 'Employees cannot approve or reject their own requests';
    end if;

    -- If cancelling, ensure decided_by stays null
    if new.status = 'cancelled' and new.decided_by is not null then
      raise exception 'Cancelled requests cannot have a decided_by';
    end if;

    -- If still pending, ensure decided_by stays null
    if new.status = 'pending' and new.decided_by is not null then
      raise exception 'Pending requests must not have decided_by';
    end if;

    -- Employee can change starts_on, ends_on, note, status (to cancelled)
    return new;
  end if;

  -- Manager updating
  if public.is_manager_of(old.employee_id) then
    -- R4: Manager can only approve or reject
    if new.status not in ('approved', 'rejected') then
      raise exception 'Managers can only approve or reject requests';
    end if;

    -- Must set decided_by to themselves
    if new.decided_by != auth.uid() then
      raise exception 'Manager must set decided_by to themselves';
    end if;

    -- Cannot change dates or note
    if new.starts_on != old.starts_on or new.ends_on != old.ends_on or new.note is distinct from old.note then
      raise exception 'Managers cannot change dates or note when deciding';
    end if;

    return new;
  end if;

  -- Neither employee nor manager
  raise exception 'Not authorized to update this leave request';
end;
$$;

