create or replace function public.validate_leave_request_update()
returns trigger
language plpgsql
security definer
as $$
begin
  -- R5: Non-pending requests cannot be modified
  if old.status <> 'pending' then
    raise exception 'Cannot modify leave request that is not pending';
  end if;

  -- Employee updating
  if old.employee_id = auth.uid() then
    -- Cannot approve/reject own request
    if new.status in ('approved', 'rejected') then
      raise exception 'Employees cannot approve or reject their own requests';
    end if;
    -- Can change to cancelled or keep pending
    if new.status = 'cancelled' then
      -- Ensure no other fields changed except status and maybe note? Actually rule says dates and note or cancel
      -- If cancelling, dates/note should stay same? R3 says "change its dates and note or cancel it"
      -- So cancel is separate from editing dates/note
      -- Allow: dates/note same as old, or allow changes? R3 implies cancel is alternative to changing dates/note
      -- Let's enforce: when cancelling, dates/note must stay same
      if new.starts_on <> old.starts_on or new.ends_on <> old.ends_on or new.note is distinct from old.note then
        raise exception 'Cannot change dates or note when cancelling';
      end if;
      -- decided_by must stay null
      if new.decided_by is not null then
        raise exception 'Cannot set decided_by when cancelling';
      end if;
    elsif new.status = 'pending' then
      -- Editing dates/note, ensure decided_by stays null
      if new.decided_by is not null then
        raise exception 'Cannot set decided_by on pending request';
      end if;
      -- Status must stay pending
      -- dates/note can change, that's the point
    else
      raise exception 'Invalid status transition';
    end if;

  -- Manager updating
  elsif public.is_manager_of(old.employee_id) then
    -- Must approve or reject
    if new.status not in ('approved', 'rejected') then
      raise exception 'Managers can only approve or reject requests';
    end if;
    -- Must record self as decided_by
    if new.decided_by <> auth.uid() then
      raise exception 'Manager must set themselves as decided_by';
    end if;
    -- Cannot change dates or note
    if new.starts_on <> old.starts_on or new.ends_on <> old.ends_on or new.note is distinct from old.note then
      raise exception 'Managers cannot change request dates or note';
    end if;
    -- Cannot change employee_id
    if new.employee_id <> old.employee_id then
      raise exception 'Cannot change employee_id';
    end if;
  else
    raise exception 'Not authorized to update this leave request';
  end if;

  return new;
end;
$$;

