-- Enable RLS on tables
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

-- Helper function: check if two users are friends (accepted friendship in either direction)
create or replace function public.are_friends(user_a uuid, user_b uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.friendships
    where status = 'accepted'
      and (
        (requester_id = user_a and addressee_id = user_b)
        or (requester_id = user_b and addressee_id = user_a)
      )
  );
$$;

-- Posts policies

-- R1: Select posts - public posts visible to all, friends posts visible to friends and self, only_me visible to self
create policy "posts_select"
  on public.posts
  for select
  using (
    audience = 'public'
    or author_id = auth.uid()
    or (
      audience = 'friends'
      and public.are_friends(author_id, auth.uid())
    )
  );

-- R2: Insert own posts only, author_id must be self
create policy "posts_insert"
  on public.posts
  for insert
  with check (
    auth.uid() is not null
    and author_id = auth.uid()
  );

-- R2: Update own posts only, author_id cannot change
create policy "posts_update"
  on public.posts
  for update
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

-- R2: Delete own posts only
create policy "posts_delete"
  on public.posts
  for delete
  using (author_id = auth.uid());

-- Friendships policies

-- R3, R4, R5: Insert friend requests - must be requester, status must be pending
create policy "friendships_insert"
  on public.friendships
  for insert
  with check (
    auth.uid() is not null
    and requester_id = auth.uid()
    and status = 'pending'
  );

-- R4: Update - only addressee can accept pending request, only status can change to accepted
create policy "friendships_update"
  on public.friendships
  for update
  using (
    auth.uid() = addressee_id
    and status = 'pending'
  )
  with check (
    auth.uid() = addressee_id
    and status = 'accepted'
  );

-- R5: Delete - either party can delete
create policy "friendships_delete"
  on public.friendships
  for delete
  using (
    auth.uid() = requester_id
    or auth.uid() = addressee_id
  );

-- R5: Select - users can see friendships they are part of
create policy "friendships_select"
  on public.friendships
  for select
  using (
    auth.uid() = requester_id
    or auth.uid() = addressee_id
  );

-- Service role bypass (R6) - service_role bypasses RLS by default, but explicit policies for clarity
-- No explicit service_role policies needed as service_role bypasses RLS

-- Revoke public access and grant appropriate permissions
revoke all on public.friendships from anon, authenticated;
revoke all on public.posts from anon, authenticated;

grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;

grant select on public.posts to anon;

grant usage on schema public to anon, authenticated;
grant execute on function public.are_friends(uuid, uuid) to authenticated;
