  on public.reviews
  for delete
  to authenticated
  using (auth.uid() = user_id);

-- Prevent users from setting is_featured via trigger
create or replace function public.reviews_prevent_featured_manipulation()
returns trigger
language plpgsql
security definer
as $$
begin
  if TG_OP = 'INSERT' then
    -- Force is_featured to false on user inserts
    new.is_featured := false;
    return new;
  elsif TG_OP = 'UPDATE' then
    -- Prevent users from changing is_featured
    -- Only allow update if is_featured is not being changed, or if caller is service_role
    if new.is_featured is distinct from old.is_featured then
      -- Check if current role is service_role via jwt claim or session variable
      -- Supabase service_role bypasses RLS, but this trigger catches direct table access too
      -- Use a check that fails for regular users: service_role has no jwt typically, but we can
      -- detect by checking if the change came through RLS bypass or via a specific indicator
      -- Actually, service_role bypasses RLS entirely, so policies don't apply. But trigger still fires.
      -- We need to allow service_role. Check pg_has_role or a session variable.
      -- Supabase sets request.jwt.claims. For service_role, there's no standard claim.
      -- Alternative: use a security definer function that checks current_setting
      begin
        if current_setting('request.jwt.claims', true)::json->>'role' = 'service_role' then
          return new;
        end if;
      exception when others then
        null;
      end;
      -- If we get here, it's not service_role via standard jwt
      -- Check if we're in a superuser/service context another way
      -- Use pg_has_role for service_role membership
      if pg_has_role(current_user, 'service_role', 'MEMBER') or
