        return new;
      end if;
      -- Otherwise reject
      raise exception 'Only staff can set is_featured';
    end if;
    -- Preserve existing is_featured if not being changed by authorized role
    new.is_featured := old.is_featured;
    return new;
  end if;
  return null;
end;
$$;

