-- Trigger to enforce is_featured cannot be changed by non-service-role users
create or replace function public.reviews_enforce_featured()
returns trigger as $$
declare
  jwt_role text;
begin
  -- Get the role from the JWT, default to 'anon' if not present
  jwt_role := coalesce(auth.jwt()->>'role', 'anon');

  -- service_role can do anything
  if jwt_role = 'service_role' then
    return new;
  end if;

  -- authenticated users cannot change is_featured on insert or update
  -- For insert: is_featured must be false (handled by policy, but defense in depth)
  -- For update: is_featured must remain the same
  if tg_op = 'INSERT' then
    if new.is_featured is distinct from false then
      raise exception 'Users cannot set is_featured to true';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.is_featured is distinct from old.is_featured then
      raise exception 'Users cannot change is_featured';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

