-- Listings SELECT policy
create policy "listings_select"
on public.listings
for select
to anon, authenticated
using (
  -- R1: anyone can see active, not flagged, not deleted listings
  (status = 'active' and is_flagged = false and deleted_at is null)
  -- R2: sellers can see their own listings
  or (auth.role() = 'authenticated' and seller_id = auth.uid())
  -- R2: moderators can see all listings
  or (auth.role() = 'authenticated' and public.is_moderator())
);

-- Listings INSERT policy
create policy "listings_insert"
on public.listings
for insert
to authenticated
with check (
  -- R3: sellers create as themselves
  seller_id = auth.uid()
  -- R3: never flagged or deleted
  and is_flagged = false
  and deleted_at is null
);

-- Listings UPDATE policy
create policy "listings_update_seller"
on public.listings
for update
to authenticated
using (
  -- R3: own listings that are not deleted
  seller_id = auth.uid()
  and deleted_at is null
  -- R4: can only set deleted_at (enforced by column-level logic in trigger)
)
with check (
  -- R3: can never flag or unflag
  is_flagged = (select is_flagged from public.listings where id = listings.id)
  -- R3, R4: seller cannot restore or change deleted status
  and deleted_at is not distinct from (select deleted_at from public.listings where id = listings.id)
    -- Actually, we need to allow setting deleted_at for removal
    -- Re-check: seller can only update non-deleted listings, and can set deleted_at
);

-- Better approach: separate policies with proper conditions
drop policy if exists "listings_update_seller" on public.listings;

create policy "listings_update_seller"
on public.listings
for update
to authenticated
using (
  seller_id = auth.uid()
  and deleted_at is null
  and not public.is_moderator()
)
with check (
  seller_id = auth.uid()
  and is_flagged = (select is_flagged from public.listings where id = listings.id)
);

-- Moderator UPDATE policy
create policy "listings_update_moderator"
on public.listings
for update
to authenticated
using (public.is_moderator())
with check (public.is_moderator());

-- Prevent DELETE on listings (R6)
create policy "listings_no_delete"
on public.listings
for delete
to anon, authenticated
using (false);

-- Moderators table: no access through app (R6)
create policy "moderators_no_access"
on public.moderators
for all
to anon, authenticated
using (false);

-- Trigger to enforce seller cannot change is_flagged
create or replace function public.enforce_listing_update_rules()
returns trigger as $$
begin
  -- R3: sellers cannot flag/unflag
  if not public.is_moderator() then
    if NEW.is_flagged is distinct from OLD.is_flagged then
      raise exception 'Sellers cannot flag or unflag listings';
    end if;
  end if;

  -- R4: once deleted, cannot be changed by seller
  if not public.is_moderator() and OLD.deleted_at is not null then
    raise exception 'Deleted listings cannot be modified';
  end if;

  -- R3: seller_id cannot be changed
  if NEW.seller_id is distinct from OLD.seller_id then
    raise exception 'Cannot change seller_id';
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

create trigger listings_update_trigger
before update on public.listings
for each row
execute function public.enforce_listing_update_rules();

-- Grant appropriate permissions
grant usage on schema public to anon, authenticated;
grant select on public.listings to anon, authenticated;
grant insert, update on public.listings to authenticated;
grant execute on function public.is_moderator to anon, authenticated;

-- Revoke delete explicitly
revoke delete on public.listings from anon, authenticated;

-- Ensure service_role has full access (R7)
grant all on public.listings to service_role;
grant all on public.moderators to service_role;
