  using (true);

-- Restaurant_staff policies (read-only for authenticated)
create policy "restaurant_staff_select_authenticated"
  on public.restaurant_staff
  for select
  to authenticated
  using (true);

-- Reservations policies

-- Select: guests see own reservations, staff see their restaurant's reservations
create policy "reservations_select_authenticated"
  on public.reservations
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or public.is_restaurant_staff(restaurant_id)
  );

-- Insert: guests can book as themselves, only future times, status must be booked
create policy "reservations_insert_authenticated"
  on public.reservations
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and reserved_for > now()
    and status = 'booked'
  );

-- Update for guests: can only cancel own booked future reservations, only change status to cancelled
create policy "reservations_update_guests"
  on public.reservations
  for update
  to authenticated
  using (
    user_id = auth.uid()
    and status = 'booked'
    and reserved_for > now()
  )
  with check (
    user_id = auth.uid()
    and status = 'cancelled'
    and reserved_for > now()
    -- Ensure other fields are not changed by comparing to old values via trigger
  );

-- Update for staff: can mark booked reservations as seated or no_show only after time passed
create policy "reservations_update_staff"
  on public.reservations
  for update
  to authenticated
  using (
    public.is_restaurant_staff(restaurant_id)
    and status = 'booked'
    and reserved_for <= now()
  )
  with check (
    public.is_restaurant_staff(restaurant_id)
    and status in ('seated', 'no_show')
  );

-- No delete allowed
-- No explicit delete policy means delete is denied for all roles except service_role (bypasses RLS)

-- Prevent non-service_role from deleting reservations
create policy "reservations_no_delete"
  on public.reservations
  for delete
  to authenticated, anon
  using (false);

-- Prevent modifications to restaurants
create policy "restaurants_no_insert"
  on public.restaurants
  for insert
  to authenticated, anon
