  on public.restaurant_staff
  for insert
  to authenticated, anon
  with check (false);

create policy "restaurant_staff_no_update"
  on public.restaurant_staff
  for update
  to authenticated, anon
  using (false);

create policy "restaurant_staff_no_delete"
  on public.restaurant_staff
  for delete
  to authenticated, anon
  using (false);

-- Trigger to enforce guest update constraints more strictly
create or replace function public.check_reservation_update()
returns trigger as $$
declare
  old_user_id uuid;
  old_restaurant_id bigint;
  old_reserved_for timestamptz;
  old_party_size integer;
begin
  -- Get old values
  old_user_id := old.user_id;
  old_restaurant_id := old.restaurant_id;
  old_reserved_for := old.reserved_for;
  old_party_size := old.party_size;

  -- If status is being changed to cancelled, verify it's by the owner and still future
  if new.status = 'cancelled' and old.status = 'booked' then
    if old_user_id != auth.uid() then
      -- Check if staff is doing this (staff policy handles seated/no_show)
      if not public.is_restaurant_staff(old_restaurant_id) then
        raise exception 'Only the guest or staff can cancel';
      end if;
    end if;
    -- Ensure only status changes
    if new.user_id != old_user_id or new.restaurant_id != old_restaurant_id 
       or new.reserved_for != old_reserved_for or new.party_size != old_party_size then
      raise exception 'Guests can only change status to cancelled';
    end if;
    return new;
  end if;

  -- If staff is changing to seated or no_show
  if new.status in ('seated', 'no_show') and old.status = 'booked' then
    if not public.is_restaurant_staff(old_restaurant_id) then
      raise exception 'Only staff can mark as seated or no_show';
    end if;
    if old.reserved_for > now() then
      raise exception 'Can only mark after reservation time has passed';
    end if;
    -- Ensure only status changes
    if new.user_id != old_user_id or new.restaurant_id != old_restaurant_id 
       or new.reserved_for != old_reserved_for or new.party_size != old_party_size then
      raise exception 'Staff can only change status';
    end if;
    return new;
  end if;

  -- Any other status change is invalid
  raise exception 'Invalid status transition from % to %', old.status, new.status;
end;
$$ language plpgsql security definer;

create trigger reservation_update_trigger
  before update on public.reservations
  for each row
  execute function public.check_reservation_update();

-- Grant appropriate permissions
grant usage on schema public to anon, authenticated;
grant select on public.restaurants to anon, authenticated;
grant select on public.restaurant_staff to authenticated;
grant select, insert, update on public.reservations to authenticated;
grant usage on sequence public.reservations_id_seq to authenticated;

-- Ensure service_role has full access (bypasses RLS but explicit grants are good practice)
grant all on public.restaurants to service_role;
grant all on public.restaurant_staff to service_role;
grant all on public.reservations to service_role;
grant all on sequence public.reservations_id_seq to service_role;
