-- Enable RLS on tables
alter table public.org_admins enable row level security;
alter table public.files enable row level security;

-- Helper function to check if current user is an org admin
create or replace function public.is_org_admin()
returns boolean as $$
begin
  return exists (
    select 1 from public.org_admins where user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- org_admins policies
-- R5: Nobody can change org_admins through the app
-- R6: Anonymous cannot see anything
-- R7: Service role bypasses RLS

create policy "org_admins_select"
  on public.org_admins
  for select
  to authenticated
  using (false);

create policy "org_admins_insert"
  on public.org_admins
  for insert
  to authenticated
  with check (false);

create policy "org_admins_update"
  on public.org_admins
  for update
  to authenticated
  using (false)
  with check (false);

create policy "org_admins_delete"
  on public.org_admins
  for delete
  to authenticated
  using (false);

-- files policies

-- SELECT: R1 - Users see own files, org admins see all files
create policy "files_select"
  on public.files
  for select
  to authenticated
  using (
    owner_id = auth.uid()
    or public.is_org_admin()
  );

-- INSERT: R2 - Users can upload files as themselves
create policy "files_insert"
  on public.files
  for insert
  to authenticated
  with check (
    owner_id = auth.uid()
  );

-- UPDATE: R2 - Users can rename own files, org admins can rename any file
-- R3 - Legal hold blocks rename
-- R4 - Cannot change legal_hold through app
create policy "files_update"
  on public.files
  for update
  to authenticated
  using (
    (owner_id = auth.uid() or public.is_org_admin())
    and legal_hold = false
  )
  with check (
    (owner_id = auth.uid() or public.is_org_admin())
    and legal_hold = false
    -- R4: legal_hold cannot be changed through app
    and legal_hold = (select legal_hold from public.files where id = files.id)
  );

-- DELETE: R2 - Users can delete own files, org admins can delete any file
-- R3 - Legal hold blocks delete
create policy "files_delete"
  on public.files
  for delete
  to authenticated
  using (
    (owner_id = auth.uid() or public.is_org_admin())
    and legal_hold = false
  );

-- Prevent anon from doing anything on files
create policy "files_anon_select"
  on public.files
  for select
  to anon
