-- Helper function: check if user is admin of org
create or replace function public.is_org_admin(p_org_id bigint, p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.org_members
    where org_id = p_org_id and user_id = p_user_id and role = 'admin'
  );
end;
$$ language plpgsql security definer;

-- Helper function: get user's verified email from JWT
create or replace function public.auth_email()
returns text as $$
begin
  return coalesce(
    nullif(current_setting('request.jwt.claims', true)::json->>'email', ''),
    nullif(current_setting('request.jwt.claim.email', true), '')
  );
end;
$$ language plpgsql stable;

-- R5: Anonymous visitors cannot see or change anything (enforced by policies)

-- Orgs policies
create policy "orgs_select_members"
  on public.orgs for select
  using (
    exists (
      select 1 from public.org_members
      where org_id = public.orgs.id and user_id = auth.uid()
    )
  );

create policy "orgs_service_all"
  on public.orgs for all
  to service_role
  using (true) with check (true);

-- Org_members policies
create policy "org_members_select_members"
  on public.org_members for select
  using (
    exists (
      select 1 from public.org_members om
      where om.org_id = public.org_members.org_id and om.user_id = auth.uid()
    )
  );

create policy "org_members_service_all"
  on public.org_members for all
  to service_role
  using (true) with check (true);

-- Invites policies
create policy "invites_select_admin"
  on public.invites for select
  using (
    public.is_org_admin(org_id, auth.uid())
  );

create policy "invites_insert_admin"
  on public.invites for insert
  with check (
    public.is_org_admin(org_id, auth.uid())
    and invited_by = auth.uid()
    and accepted_at is null
    and expires_at > now()
  );

create policy "invites_delete_admin"
  on public.invites for delete
  using (
    public.is_org_admin(org_id, auth.uid())
  );

create policy "invites_service_all"
  on public.invites for all
  to service_role
  using (true) with check (true);

-- accept_invite function
create or replace function public.accept_invite(p_token text)
returns bigint as $$
declare
  v_invite public.invites%rowtype;
  v_email text;
begin
  -- Check user is signed in
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  -- Get verified email from JWT (ignore user_metadata)
  v_email := lower(public.auth_email());
  if v_email is null or v_email = '' then
    raise exception 'No verified email in JWT';
  end if;

  -- Get and lock the invite
  select * into v_invite
  from public.invites
  where token = p_token
  for update;

  -- Check invite exists
  if not found then
    raise exception 'Unknown invite token';
  end if;

  -- Check not already accepted
  if v_invite.accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- Check not expired
  if v_invite.expires_at <= now() then
    raise exception 'Invite expired';
  end if;

  -- Check email matches (case-insensitive)
  if lower(v_invite.email) != v_email then
    raise exception 'Invite email does not match verified email';
  end if;

  -- Check not already a member
  if exists (
    select 1 from public.org_members
    where org_id = v_invite.org_id and user_id = auth.uid()
  ) then
    raise exception 'Already a member of this organization';
  end if;

  -- Add membership
  insert into public.org_members (org_id, user_id, role)
  values (v_invite.org_id, auth.uid(), v_invite.role);

  -- Mark invite accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_invite.org_id;
end;
$$ language plpgsql security definer;

-- Revoke execute from public, grant to authenticated
revoke execute on function public.accept_invite(text) from public;
grant execute on function public.accept_invite(text) to authenticated;
grant execute on function public.accept_invite(text) to service_role;

-- Ensure service_role has full table access
grant all on public.orgs to service_role;
grant all on public.org_members to service_role;
grant all on public.invites to service_role;

-- Grant authenticated necessary sequence access if needed (for bigint PKs, no sequences defined)
-- Grant select on orgs, org_members to authenticated for RLS policies
grant select on public.orgs to authenticated;
grant select on public.org_members to authenticated;
grant select, insert, delete on public.invites to authenticated;

-- Revoke all from anon on tables
revoke all on public.orgs from anon;
revoke all on public.org_members from anon;
revoke all on public.invites from anon;
