-- accept_invite RPC function
create or replace function public.accept_invite(p_token text)
returns bigint as $$
declare
  v_invite record;
  v_org_id bigint;
  v_user_email text;
begin
  -- Check user is signed in
  if auth.uid() is null then
    raise exception 'Must be signed in to accept invite';
  end if;

  -- Get user's verified email from JWT (not user_metadata)
  v_user_email := public.get_user_email();
  if v_user_email = '' then
    raise exception 'No verified email found in JWT';
  end if;

  -- Get and lock the invite
  select * into v_invite
  from public.invites
  where token = p_token
  for update;

  -- Check token exists
  if not found then
    raise exception 'Unknown invite token';
  end if;

  -- Check not already accepted
  if v_invite.accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- Check not expired
  if v_invite.expires_at <= now() then
    raise exception 'Invite expired';
  end if;

  -- Check email matches (case-insensitive)
  if lower(v_invite.email) != lower(v_user_email) then
    raise exception 'Invite email does not match your verified email';
  end if;

  -- Add membership
  insert into public.org_members (org_id, user_id, role)
  values (v_invite.org_id, auth.uid(), v_invite.role)
  on conflict (org_id, user_id) do nothing;

  -- Mark invite accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_invite.org_id;
end;
$$ language plpgsql security definer;

