on public.categories
for insert
to authenticated
with check (user_id = auth.uid());

-- R2: Users can update only their own categories
create policy "allow_update_own_categories"
on public.categories
for update
to authenticated
using (user_id = auth.uid())
with check (user_id = auth.uid() and user_id is not null);

-- R2: Users can delete only their own categories
create policy "allow_delete_own_categories"
on public.categories
for delete
to authenticated
using (user_id = auth.uid());

-- R4: Explicitly deny anon all access (no policies for anon = deny, but explicit revoke for clarity)
-- No select/insert/update/delete policies for anon

