-- Helper function to prevent turning user category into built-in (additional guard)
create or replace function public.prevent_builtin_conversion()
returns trigger
language plpgsql
security definer
as $$
begin
  -- R3: Prevent changing a built-in category (user_id was null)
  if old.user_id is null and new.user_id is null then
    raise exception 'Built-in categories cannot be modified';
  end if;

  -- R3: Prevent turning a user category into built-in
  if old.user_id is not null and new.user_id is null then
    raise exception 'Cannot convert user category to built-in';
  end if;

  -- R3: Prevent changing user_id to another user
  if old.user_id is not null and new.user_id <> old.user_id then
    raise exception 'Cannot change category owner';
  end if;

  return new;
end;
$$;

create trigger trg_prevent_builtin_conversion
before update on public.categories
for each row
execute function public.prevent_builtin_conversion();

-- Additional trigger to prevent deleting built-in categories
