returns trigger
language plpgsql
security definer
as $$
begin
  if old.user_id is null then
    raise exception 'Built-in categories cannot be deleted';
  end if;
  return old;
end;
$$;

create trigger trg_prevent_builtin_delete
before delete on public.categories
for each row
execute function public.prevent_builtin_delete();

-- Ensure no one can insert built-in categories through the app
create or replace function public.prevent_builtin_insert()
returns trigger
language plpgsql
security definer
as $$
