-- Matches: <uuid>.png or <uuid>.jpg at top level (no folders, name = path_tokens[-1])
create policy "Allow users to manage own avatar"
on storage.objects
for all
to authenticated
using (
    bucket_id = 'avatars'
    and owner = auth.uid()
    and path_tokens = array[name]
    and name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpg)$'
    and name = (auth.uid())::text || substr(name, 37) -- verify prefix is user's UUID
)
with check (
    bucket_id = 'avatars'
    and owner = auth.uid()
    and path_tokens = array[name]
    and name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpg)$'
);

-- R3: Explicit deny for other buckets (defense in depth, but using() false blocks all ops)
-- Note: This is redundant with R2's bucket_id check, but ensures explicit deny
-- Actually, policies are OR-combined for same role, so we need to be careful.
-- Instead, we rely on R2's restrictive conditions. For anon, only select on avatars works.
-- For authenticated, only their own avatar works for all ops, and select on avatars works via R1.

-- R4: Anonymous cannot upload/change/delete - enforced by only having SELECT policy for anon
-- (No INSERT/UPDATE/DELETE policies for anon)

-- R5: Service role bypasses RLS by default, but we'll add explicit policy for completeness
create policy "Allow service role full access"
on storage.objects
for all
to service_role
using (true)
with check (true);

-- Ensure no other policies grant unintended access
-- The combination of policies means:
-- - anon: SELECT only on avatars (R1)
-- - authenticated: SELECT on avatars (R1), ALL on own avatar (R2)
-- - service_role: ALL on everything (R5 + bypass)

-- Additional safety: revoke public from storage schema except needed roles
-- (Supabase default grants are typically fine, but we ensure proper grants)

-- Grant usage on storage schema to authenticated and anon (needed for RLS policies)
grant usage on schema storage to anon, authenticated, service_role;

-- Ensure sequences and tables have proper grants for the operations
grant select on storage.buckets to anon, authenticated;
grant select, insert, update, delete on storage.objects to authenticated, service_role;
grant select on storage.objects to anon;

