-- The regex approach in the main policy is sufficient and more performant

-- Trigger to enforce owner is set correctly on insert/update for avatars bucket
create or replace function storage.enforce_avatar_owner()
returns trigger
language plpgsql
security definer
as $$
begin
    if new.bucket_id = 'avatars' then
        -- Ensure owner matches the filename prefix
        if new.owner is null or new.owner::text != split_part(new.name, '.', 1) then
            raise exception 'Avatar owner must match filename UUID prefix';
        end if;
        -- Ensure no subdirectories
        if array_length(new.path_tokens, 1) != 1 then
            raise exception 'Avatars must be at bucket root';
        end if;
    end if;
    return new;
end;
$$;

