create or replace function public.check_seat_availability()
returns trigger as $$
begin
  if new.status = 'confirmed' and old.status != 'confirmed' then
    if public.confirmed_booking_count(new.ride_id) >= (
      select seats from public.rides where id = new.ride_id
    ) then
      raise exception 'No seats available for this ride';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trg_check_seat_availability
  before update on public.ride_bookings
  for each row
  execute function public.check_seat_availability();

-- Trigger to prevent any other column changes on bookings
create or replace function public.restrict_booking_updates()
returns trigger as $$
begin
  if old.ride_id != new.ride_id or old.passenger_id != new.passenger_id then
    raise exception 'Cannot change ride_id or passenger_id';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trg_restrict_booking_updates
  before update on public.ride_bookings
  for each row
  execute function public.restrict_booking_updates();

