alter table public.approvers enable row level security;
alter table public.purchase_orders enable row level security;
alter table public.po_approvals enable row level security;

-- Helper function to check if a purchase order is decided
create or replace function public.is_po_decided(po_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists(select 1 from public.po_approvals where po_approvals.po_id = is_po_decided.po_id);
$$;

-- Helper function to check if user is an approver
create or replace function public.is_approver(user_uuid uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists(select 1 from public.approvers where approvers.user_id = is_approver.user_uuid);
$$;

-- Helper function to get approver limit
create or replace function public.get_approver_limit(user_uuid uuid)
returns numeric(12, 2)
language sql
security definer
stable
as $$
  select limit_amount from public.approvers where approvers.user_id = user_uuid;
$$;

-- approvers policies
create policy "approvers_select_own"
  on public.approvers
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "approvers_service_role"
  on public.approvers
  for all
  to service_role
  using (true)
  with check (true);

-- purchase_orders policies
create policy "po_select_requester_or_approver"
  on public.purchase_orders
  for select
  to authenticated
  using (
    requester_id = auth.uid()
    or public.is_approver(auth.uid())
  );

create policy "po_insert_own"
  on public.purchase_orders
  for insert
  to authenticated
  with check (requester_id = auth.uid());

create policy "po_update_own_undecided"
  on public.purchase_orders
  for update
  to authenticated
  using (
    requester_id = auth.uid()
    and not public.is_po_decided(id)
  )
  with check (requester_id = auth.uid());

create policy "po_delete_own_undecided"
  on public.purchase_orders
  for delete
  to authenticated
  using (
    requester_id = auth.uid()
    and not public.is_po_decided(id)
  );

create policy "po_service_role"
  on public.purchase_orders
  for all
  to service_role
  using (true)
  with check (true);

-- po_approvals policies
create policy "pa_select_requester_or_approver"
  on public.po_approvals
  for select
  to authenticated
  using (
    exists(select 1 from public.purchase_orders where purchase_orders.id = po_approvals.po_id and purchase_orders.requester_id = auth.uid())
    or public.is_approver(auth.uid())
  );

create policy "pa_insert_approver_within_limit"
  on public.po_approvals
  for insert
  to authenticated
  with check (
    approver_id = auth.uid()
    and public.is_approver(auth.uid())
    and exists(
      select 1 from public.purchase_orders
      where purchase_orders.id = po_approvals.po_id
      and purchase_orders.requester_id != auth.uid()
      and purchase_orders.amount <= public.get_approver_limit(auth.uid())
      and not public.is_po_decided(purchase_orders.id)
    )
  );

create policy "pa_service_role"
  on public.po_approvals
  for all
  to service_role
  using (true)
  with check (true);

-- Revoke public access and grant to authenticated and service_role
revoke all on public.approvers from anon, authenticated;
revoke all on public.purchase_orders from anon, authenticated;
revoke all on public.po_approvals from anon, authenticated;

grant select on public.approvers to authenticated;
grant select, insert, update, delete on public.purchase_orders to authenticated;
grant select, insert on public.po_approvals to authenticated;

grant all on public.approvers to service_role;
grant all on public.purchase_orders to service_role;
grant all on public.po_approvals to service_role;

-- Grant usage on helper functions
grant execute on function public.is_po_decided to authenticated, service_role;
grant execute on function public.is_approver to authenticated, service_role;
grant execute on function public.get_approver_limit to authenticated, service_role;

-- Ensure sequences are accessible
grant usage, select on all sequences in schema public to authenticated, service_role;
