-- Enable RLS on all tables
alter table public.classes enable row level security;
alter table public.class_students enable row level security;
alter table public.guardians enable row level security;
alter table public.grades enable row level security;

-- Helper function: check if user is a teacher of a class
create or replace function public.is_teacher_of_class(p_class_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.classes
    where id = p_class_id and teacher_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user is a guardian of a student
create or replace function public.is_guardian_of_student(p_student_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.guardians
    where guardian_id = auth.uid() and student_id = p_student_id
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user is enrolled in a class
create or replace function public.is_enrolled_in_class(p_class_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.class_students
    where class_id = p_class_id and student_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if student is enrolled in a class
create or replace function public.student_is_enrolled(p_class_id bigint, p_student_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.class_students
    where class_id = p_class_id and student_id = p_student_id
  );
end;
$$ language plpgsql security definer;

-- ============================================
-- POLICIES FOR public.grades
-- ============================================

-- R1: Students can read their own grades
create policy "grades_select_student"
  on public.grades
  for select
  to authenticated
  using (student_id = auth.uid());

-- R1: Guardians can read grades of students they guard
create policy "grades_select_guardian"
  on public.grades
  for select
  to authenticated
  using (is_guardian_of_student(student_id));

-- R1: Teachers can read every grade in classes they teach
create policy "grades_select_teacher"
  on public.grades
  for select
  to authenticated
  using (is_teacher_of_class(class_id));

-- R2: Teachers can insert grades for students in their classes, with themselves as graded_by
create policy "grades_insert_teacher"
  on public.grades
  for insert
  to authenticated
  with check (
    is_teacher_of_class(class_id)
    and student_is_enrolled(class_id, student_id)
    and graded_by = auth.uid()
  );

-- R2: Teachers can update grades in classes they teach
create policy "grades_update_teacher"
  on public.grades
  for update
  to authenticated
  using (is_teacher_of_class(class_id))
  with check (
    is_teacher_of_class(class_id)
    and student_is_enrolled(class_id, student_id)
    and graded_by = auth.uid()
  );

-- R2: Teachers can delete grades in classes they teach
create policy "grades_delete_teacher"
  on public.grades
  for delete
  to authenticated
  using (is_teacher_of_class(class_id));

-- ============================================
-- POLICIES FOR public.classes
-- ============================================

-- R4: Signed-in users can see the class list
create policy "classes_select_authenticated"
  on public.classes
  for select
  to authenticated
  using (true);

-- R4: Nobody can modify classes through the app
-- (no insert/update/delete policies for authenticated)

-- ============================================
-- POLICIES FOR public.class_students
-- ============================================

-- R4: Students can see their own enrollments
create policy "class_students_select_self"
  on public.class_students
  for select
  to authenticated
  using (student_id = auth.uid());

-- R4: Teachers can see rosters of their classes
create policy "class_students_select_teacher"
  on public.class_students
  for select
  to authenticated
  using (is_teacher_of_class(class_id));

-- R4: Nobody can modify enrollments through the app
-- (no insert/update/delete policies for authenticated)

-- ============================================
-- POLICIES FOR public.guardians
-- ============================================

-- R4: Users can see guardian links that involve them
create policy "guardians_select_involved"
  on public.guardians
  for select
  to authenticated
  using (guardian_id = auth.uid() or student_id = auth.uid());

-- R4: Nobody can modify guardian links through the app
-- (no insert/update/delete policies for authenticated)

-- ============================================
-- REVOKE AND GRANT (ensure service_role has access)
-- ============================================

-- Ensure authenticated role cannot bypass RLS (default, but explicit)
-- Service role bypasses RLS by default in Supabase

-- Grant necessary table permissions to authenticated
grant select on public.classes to authenticated;
grant select on public.class_students to authenticated;
grant select on public.guardians to authenticated;
grant select, insert, update, delete on public.grades to authenticated;

-- Grant sequence usage for grades insert
grant usage on sequence public.grades_id_seq to authenticated;

-- Ensure service_role has full access
grant all on public.classes to service_role;
grant all on public.class_students to service_role;
grant all on public.guardians to service_role;
grant all on public.grades to service_role;
grant all on sequence public.grades_id_seq to service_role;
