-- Helper function: check if user is staff at location
create or replace function public.is_location_staff(p_location_id bigint, p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.location_staff
    where location_id = p_location_id and user_id = p_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user is auditor
create or replace function public.is_auditor(p_user_id uuid)
returns boolean as $$
declare
  jwt_role text;
begin
  jwt_role := auth.jwt() -> 'app_metadata' ->> 'role';
  return jwt_role = 'auditor';
end;
$$ language plpgsql security definer;

-- Helper function: check if location is frozen
create or replace function public.is_location_frozen(p_location_id bigint)
returns boolean as $$
declare
  frozen boolean;
begin
  select is_frozen into frozen from public.locations where id = p_location_id;
  return coalesce(frozen, false);
end;
$$ language plpgsql security definer;

-- LOCATIONS policies
-- R1: signed-in users can see locations, R6: anon cannot
create policy "locations_select_authenticated"
  on public.locations
  for select
  to authenticated
  using (true);

-- R5: nobody can change locations through app, R7: service_role bypasses
-- No insert/update/delete policies for authenticated, so only service_role can modify

-- LOCATION_STAFF policies
-- R1: staff can see staff list of their own locations, auditors can see all
create policy "location_staff_select_staff"
  on public.location_staff
  for select
  to authenticated
  using (
    public.is_auditor(auth.uid()) or
    public.is_location_staff(location_id, auth.uid())
  );

-- R5: nobody can change staff lists through app
-- No insert/update/delete policies for authenticated

-- STOCK policies
-- R1: staff can see stock of their own locations, auditors can see all
create policy "stock_select_staff"
  on public.stock
  for select
  to authenticated
  using (
    public.is_auditor(auth.uid()) or
    public.is_location_staff(location_id, auth.uid())
  );

-- R2: staff can add stock at their own locations, R3: not if frozen, R4: auditors cannot
create policy "stock_insert_staff"
  on public.stock
  for insert
  to authenticated
  with check (
    not public.is_auditor(auth.uid()) and
    public.is_location_staff(location_id, auth.uid()) and
    not public.is_location_frozen(location_id)
  );

-- R2: staff can change stock at their own locations, R3: not if frozen, R4: auditors cannot
create policy "stock_update_staff"
  on public.stock
  for update
  to authenticated
  using (
    not public.is_auditor(auth.uid()) and
    public.is_location_staff(location_id, auth.uid()) and
    not public.is_location_frozen(location_id)
  )
  with check (
    not public.is_auditor(auth.uid()) and
    public.is_location_staff(location_id, auth.uid()) and
    not public.is_location_frozen(location_id)
  );

-- R2: staff can remove stock at their own locations, R3: not if frozen, R4: auditors cannot
create policy "stock_delete_staff"
  on public.stock
  for delete
  to authenticated
  using (
    not public.is_auditor(auth.uid()) and
    public.is_location_staff(location_id, auth.uid()) and
    not public.is_location_frozen(location_id)
  );

-- Ensure anon has no access (explicit revoke/deny pattern via no policies)
