returns boolean as $$
declare
  current_id bigint;
begin
  current_id := folder_id;
  while current_id is not null loop
    if exists (
      select 1 from public.folder_grants g 
      where g.folder_id = current_id and g.user_id = user_id 
      and (not require_edit or g.can_edit)
    ) then
      return true;
    end if;
    select f.parent_id into current_id from public.folders f where f.id = current_id;
  end loop;
  return false;
end;
