-- Helper function: check if user has read access to a folder (owns or has grant on folder or any ancestor)
create or replace function public.has_folder_read_access(p_folder_id bigint, p_user_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
    v_current_id bigint;
begin
    if p_user_id is null then
        return false;
    end if;

    v_current_id := p_folder_id;
    while v_current_id is not null loop
        -- Check ownership
        if exists (select 1 from public.folders f where f.id = v_current_id and f.owner_id = p_user_id) then
            return true;
        end if;
        -- Check grant
        if exists (select 1 from public.folder_grants fg where fg.folder_id = v_current_id and fg.user_id = p_user_id) then
            return true;
        end if;
        -- Move up tree
        select f.parent_id into v_current_id from public.folders f where f.id = v_current_id;
    end loop;
    return false;
end;
$$;

-- Helper function: check if user has edit access to a folder (owns or has edit grant on folder or any ancestor)
create or replace function public.has_folder_edit_access(p_folder_id bigint, p_user_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
    v_current_id bigint;
begin
    if p_user_id is null then
        return false;
    end if;

    v_current_id := p_folder_id;
    while v_current_id is not null loop
        -- Check ownership
        if exists (select 1 from public.folders f where f.id = v_current_id and f.owner_id = p_user_id) then
            return true;
        end if;
        -- Check edit grant
        if exists (select 1 from public.folder_grants fg where fg.folder_id = v_current_id and fg.user_id = p_user_id and fg.can_edit = true) then
            return true;
        end if;
        -- Move up tree
        select f.parent_id into v_current_id from public.folders f where f.id = v_current_id;
    end loop;
    return false;
end;
$$;

-- Helper function: check if user owns a folder or any ancestor (for grant management and subfolder creation)
create or replace function public.has_folder_ownership(p_folder_id bigint, p_user_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
    v_current_id bigint;
begin
    if p_user_id is null then
        return false;
    end if;

    v_current_id := p_folder_id;
    while v_current_id is not null loop
        -- Check ownership
        if exists (select 1 from public.folders f where f.id = v_current_id and f.owner_id = p_user_id) then
            return true;
        end if;
        -- Move up tree
        select f.parent_id into v_current_id from public.folders f where f.id = v_current_id;
    end loop;
    return false;
end;
$$;

-- Helper function: get all folder IDs accessible for reading (for performance in some contexts)
-- Not directly used in policies but available for views/complex queries
create or replace function public.get_accessible_folder_ids(p_user_id uuid)
returns table (folder_id bigint)
language plpgsql
security definer
set search_path = public
as $$
begin
    if p_user_id is null then
        return;
    end if;

    return query
    with recursive folder_tree as (
        select id, parent_id from public.folders
    ),
    ancestors as (
        select ft.id as folder_id, ft.id as ancestor_id
        from folder_tree ft
        union all
        select a.folder_id, ft.parent_id
        from ancestors a
        join folder_tree ft on ft.id = a.ancestor_id
        where ft.parent_id is not null
    )
    select distinct a.folder_id
    from ancestors a
    where exists (
        select 1 from public.folders f 
        where f.id = a.ancestor_id and f.owner_id = p_user_id
    ) or exists (
        select 1 from public.folder_grants fg 
        where fg.folder_id = a.ancestor_id and fg.user_id = p_user_id
    );
end;
$$;

