  );
end;
$$ language plpgsql security definer;

create or replace function public.approve_access(p_request_id bigint)
returns text as $$
declare
  v_caller_id uuid := auth.uid();
  v_requester_id uuid;
  v_status text;
  v_approval_count bigint;
begin
  if v_caller_id is null then
    raise exception 'Must be authenticated';
  end if;

  if not public.is_ops_team_member(v_caller_id) then
    raise exception 'Caller is not on the ops team';
  end if;

  select requester_id, status into v_requester_id, v_status
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Request does not exist';
  end if;

  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  if v_requester_id = v_caller_id then
    raise exception 'Cannot approve your own request';
  end if;

  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id and approver_id = v_caller_id
  ) then
    raise exception 'Already approved this request';
  end if;

  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, v_caller_id, now());

  select count(distinct approver_id) into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    v_status := 'granted';
  else
    v_status := 'pending';
  end if;

  return v_status;
end;
$$ language plpgsql security definer;

