  return exists (select 1 from public.ops_team where user_id = p_user_id);
end;
$$ language plpgsql security definer;

-- R4: approve_access function
create or replace function public.approve_access(p_request_id bigint)
returns text as $$
declare
  v_requester_id uuid;
  v_status text;
  v_approval_count int;
begin
  -- Check caller is ops team
  if not public.is_ops_team() then
    raise exception 'Caller is not on the ops team';
  end if;

  -- Get request details and lock row
  select requester_id, status into v_requester_id, v_status
  from public.access_requests
  where id = p_request_id
  for update;

  -- Check request exists and is pending
  if v_requester_id is null then
    raise exception 'Request does not exist';
  end if;

  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  -- Check caller didn't make the request
  if v_requester_id = auth.uid() then
    raise exception 'Cannot approve your own request';
  end if;

  -- Check caller hasn't already approved
  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = auth.uid()) then
    raise exception 'Already approved this request';
  end if;

  -- Record approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- Count approvals from different ops team members
  select count(*) into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  -- Grant if two or more approvals
  if v_approval_count >= 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end;
