  -- Count unique ops team approvals
  select count(distinct approver_id) into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  -- Grant if two different ops team members have approved
  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    v_status := 'granted';
  else
    v_status := 'pending';
  end if;

  return v_status;
end;
$$ language plpgsql security definer;

