returns boolean as $$
declare
  deck_owner uuid;
begin
  select owner_id into deck_owner from public.decks where id = deck_id;
  return auth.uid() = deck_owner;
end;
$$ language plpgsql security definer;

-- Helper function to prevent moving cards to another owner's deck
create or replace function public.check_card_deck_owner()
returns trigger as $$
declare
  new_deck_owner uuid;
  old_deck_owner uuid;
begin
  -- Get owner of the new deck (for insert or update)
  if TG_OP = 'INSERT' or (TG_OP = 'UPDATE' and NEW.deck_id is distinct from OLD.deck_id) then
    select owner_id into new_deck_owner from public.decks where id = NEW.deck_id;

    if new_deck_owner is null then
      raise exception 'Deck does not exist';
    end if;

    if new_deck_owner != auth.uid() then
      raise exception 'Cannot add or move cards to a deck owned by another user';
    end if;
  end if;

  -- For update, also verify old deck was owned by current user (unless service role)
  if TG_OP = 'UPDATE' and auth.role() != 'service_role' then
    select owner_id into old_deck_owner from public.decks where id = OLD.deck_id;
    if old_deck_owner != auth.uid() then
      raise exception 'Cannot modify cards in a deck owned by another user';
    end if;
  end if;

  -- For insert, verify new deck is owned by current user (already checked above)
  -- For delete, let the policy handle it

  return NEW;
end;
$$ language plpgsql security definer;

