  on public.decks
  for insert
  with check (
    auth.role() = 'authenticated'
    and auth.uid() = owner_id
  );

create policy "decks_update_owner"
  on public.decks
  for update
  using (is_deck_owner(owner_id))
  with check (is_deck_owner(owner_id));

create policy "decks_delete_owner"
  on public.decks
  for delete
  using (is_deck_owner(owner_id));

-- Cards policies

create policy "cards_select_public_or_owned"
  on public.cards
  for select
  using (
    exists (
      select 1 from public.decks d
      where d.id = cards.deck_id
      and (d.is_public = true or is_deck_owner(d.owner_id))
    )
  );

create policy "cards_insert_owner"
  on public.cards
  for insert
  with check (
    auth.role() = 'authenticated'
    and is_deck_owner_by_id(deck_id)
  );

create policy "cards_update_owner"
  on public.cards
  for update
  using (
    auth.role() = 'service_role'
    or exists (
      select 1 from public.decks d
      where d.id = cards.deck_id
      and is_deck_owner(d.owner_id)
    )
  )
  with check (
    auth.role() = 'service_role'
    or is_deck_owner_by_id(deck_id)
  );

create policy "cards_delete_owner"
  on public.cards
  for delete
  using (
    exists (
      select 1 from public.decks d
      where d.id = cards.deck_id
      and is_deck_owner(d.owner_id)
    )
  );

-- Ensure service_role bypasses RLS (default in Supabase, but explicit grants for completeness)
grant all on public.decks to service_role;
grant all on public.cards to service_role;
grant all on public.is_deck_owner to service_role;
grant all on public.is_deck_owner_by_id to service_role;
grant all on public.check_card_deck_owner to service_role;

-- Authenticated users
grant select, insert, update, delete on public.decks to authenticated;
grant select, insert, update, delete on public.cards to authenticated;
grant execute on function public.is_deck_owner to authenticated;
grant execute on function public.is_deck_owner_by_id to authenticated;

