  if not public.is_editor() and new.updated_by is distinct from auth.uid() then
    raise exception 'Non-editors must set updated_by to their own user ID';
  end if;

  -- Non-editors cannot edit protected pages
  if old.is_protected and not public.is_editor() then
    raise exception 'Only editors can edit protected pages';
  end if;

  return new;
