$$ language plpgsql security definer;

-- Helper function: check if user can see an issue
create or replace function public.can_see_issue(p_issue_id bigint, p_user_id uuid default auth.uid())
returns boolean as $$
declare
  v_project_id bigint;
  v_is_confidential boolean;
  v_reporter_id uuid;
  v_assignee_id uuid;
  v_user_role text;
begin
  select i.project_id, i.is_confidential, i.reporter_id, i.assignee_id
  into v_project_id, v_is_confidential, v_reporter_id, v_assignee_id
  from public.issues i
  where i.id = p_issue_id;

  if v_project_id is null then
    return false;
  end if;

  -- Must be project member
  if not public.is_project_member(v_project_id, p_user_id) then
    return false;
  end if;

  -- Non-confidential issues visible to all members
  if not v_is_confidential then
    return true;
  end if;

  -- Confidential issues: maintainers, reporter, or assignee only
  v_user_role := public.get_project_role(v_project_id, p_user_id);

  if v_user_role = 'maintainer' then
    return true;
  end if;

  if v_reporter_id = p_user_id then
    return true;
  end if;

  if v_assignee_id = p_user_id then
    return true;
  end if;

  return false;
end;
$$ language plpgsql security definer;

