returns trigger as $$
declare
  old_confidential boolean;
  new_confidential boolean;
begin
  -- prevent changing project_id
  if new.project_id is distinct from old.project_id then
    raise exception 'Cannot change project_id';
  end if;

  -- prevent changing reporter_id
  if new.reporter_id is distinct from old.reporter_id then
    raise exception 'Cannot change reporter_id';
  end if;

  -- check confidentiality changes
  old_confidential := old.is_confidential;
  new_confidential := new.is_confidential;

  if old_confidential is distinct from new_confidential then
    if not public.is_project_maintainer(old.project_id) then
      raise exception 'Only maintainers can change confidentiality';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

