    select 1 from public.doc_access
    where doc_id = p_doc_id and user_id = p_user_id and can_edit = true
  );
$$;

-- R3: checkout_document
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
as $$
declare
  v_doc public.documents%rowtype;
begin
  -- Lock the row and get document
  select * into v_doc from public.documents where id = p_doc_id for update;

  -- Check document exists
  if v_doc.id is null then
    raise exception 'Document % does not exist', p_doc_id;
  end if;

  -- Check caller has edit access
  if not public.has_edit_access(p_doc_id, auth.uid()) then
    raise exception 'No edit access to document %', p_doc_id;
  end if;

  -- Check if someone else has it checked out
  if v_doc.checked_out_by is not null and v_doc.checked_out_by != auth.uid() then
    raise exception 'Document % is already checked out by another user', p_doc_id;
  end if;

  -- Already checked out by caller: no-op (succeeds)
  if v_doc.checked_out_by = auth.uid() then
    return;
  end if;

  -- Check out the document
  update public.documents set checked_out_by = auth.uid() where id = p_doc_id;
end;
$$;

