returns void
language plpgsql
security definer
as $$
declare
  v_doc public.documents%rowtype;
begin
  -- Lock the row and get document
  select * into v_doc from public.documents where id = p_doc_id for update;

  -- Check document exists
  if v_doc.id is null then
    raise exception 'Document % does not exist', p_doc_id;
  end if;

  -- Check caller currently has it checked out
  if v_doc.checked_out_by is null or v_doc.checked_out_by != auth.uid() then
    raise exception 'Document % is not checked out by you', p_doc_id;
  end if;

  -- Save body and release lock
  update public.documents 
  set body = p_body, checked_out_by = null 
  where id = p_doc_id;
end;
$$;

