-- Enable Row Level Security on tables
alter table public.workouts enable row level security;
alter table public.workout_sets enable row level security;

-- Helper function to check if current user owns a specific workout
create or replace function public.is_workout_owner(p_workout_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.workouts w
    where w.id = p_workout_id and w.user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function to get user_id from a workout_id
create or replace function public.get_workout_user_id(p_workout_id bigint)
returns uuid as $$
declare
  v_user_id uuid;
begin
  select user_id into v_user_id
  from public.workouts
  where id = p_workout_id;
  return v_user_id;
end;
$$ language plpgsql security definer;

-- Policies for public.workouts

create policy "workouts_select_own"
on public.workouts
for select
to authenticated
using (user_id = auth.uid());

create policy "workouts_insert_own"
on public.workouts
for insert
to authenticated
with check (user_id = auth.uid());

create policy "workouts_update_own"
on public.workouts
for update
to authenticated
using (user_id = auth.uid())
with check (user_id = auth.uid());

create policy "workouts_delete_own"
on public.workouts
for delete
to authenticated
using (user_id = auth.uid());

-- Policies for public.workout_sets

create policy "workout_sets_select_own"
on public.workout_sets
for select
to authenticated
using (public.is_workout_owner(workout_id));

create policy "workout_sets_insert_own"
on public.workout_sets
for insert
to authenticated
with check (
  public.is_workout_owner(workout_id)
  and public.get_workout_user_id(workout_id) = auth.uid()
);

create policy "workout_sets_update_own"
on public.workout_sets
for update
to authenticated
using (public.is_workout_owner(workout_id))
with check (
  public.is_workout_owner(workout_id)
  and public.get_workout_user_id(workout_id) = auth.uid()
);

create policy "workout_sets_delete_own"
on public.workout_sets
for delete
to authenticated
using (public.is_workout_owner(workout_id));

-- Trigger to prevent moving a set to another user's workout
create or replace function public.check_workout_set_workout_change()
returns trigger as $$
begin
  -- Only check on update when workout_id is actually changing
  if TG_OP = 'UPDATE' and NEW.workout_id is distinct from OLD.workout_id then
    -- Prevent moving to a workout owned by a different user
    if public.get_workout_user_id(NEW.workout_id) is distinct from auth.uid() then
      raise exception 'Cannot move set to another user''s workout';
    end if;
  end if;
  return NEW;
end;
$$ language plpgsql security definer;

create trigger workout_sets_prevent_cross_user_move
before update on public.workout_sets
for each row
execute function public.check_workout_set_workout_change();

-- Revoke all from anon on both tables (defense in depth)
revoke all on public.workouts from anon;
revoke all on public.workout_sets from anon;

-- Ensure authenticated has appropriate base access
grant select, insert, update, delete on public.workouts to authenticated;
grant select, insert, update, delete on public.workout_sets to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
grant all on public.workouts to service_role;
grant all on public.workout_sets to service_role;
grant all on sequence public.workouts_id_seq to service_role;
grant all on sequence public.workout_sets_id_seq to service_role;

-- Grant usage on helper functions to authenticated
grant execute on function public.is_workout_owner(bigint) to authenticated;
grant execute on function public.get_workout_user_id(bigint) to authenticated;
