    -- not private and not expired
    (not paste_row.is_private and (paste_row.expires_at is null or paste_row.expires_at > now()))
    -- or is the author (signed-in users can see their own private/expired pastes)
    or (user_id is not null and paste_row.author_id = user_id)
  );
end;
