-- Trigger function to enforce status='open' on insert and prevent status changes by residents
create or replace function public.enforce_request_insert_rules()
returns trigger as $$
begin
  -- Force status to 'open' on insert
  new.status := 'open';

  -- Ensure created_by is the current user
  if new.created_by != auth.uid() then
    raise exception 'created_by must be the current user';
  end if;

  -- Ensure user is resident of the unit
  if not public.is_resident_of_unit(new.unit_id, auth.uid()) then
    raise exception 'user must be resident of the unit';
  end if;

  return new;
end;
$$ language plpgsql security definer;

