  before insert on public.requests
  for each row
  execute function public.enforce_request_insert_rules();

-- Trigger function to restrict updates to requests
create or replace function public.enforce_request_update_rules()
returns trigger as $$
begin
  -- Prevent deletion
  if tg_op = 'DELETE' then
    raise exception 'requests cannot be deleted';
  end if;

  -- Only allow status changes by staff of the building
  if new.status != old.status then
    if not public.is_staff_of_unit(old.unit_id, auth.uid()) then
      raise exception 'only building staff can change request status';
    end if;
    -- Only status can change, everything else must stay the same
    if new.id != old.id or new.unit_id != old.unit_id or new.created_by != old.created_by or new.description != old.description then
      raise exception 'only status can be updated';
    end if;
  else
    raise exception 'only status can be updated';
  end if;

  return new;
end;
$$ language plpgsql security definer;

create trigger tr_enforce_request_update_rules
  before update on public.requests
  for each row
  execute function public.enforce_request_update_rules();

