```sql
-- Enable RLS on all tables
alter table public.courses enable row level security;
alter table public.enrollments enable row level security;
alter table public.threads enable row level security;
alter table public.posts enable row level security;

-- Helper function: check if user is a member of a course
create or replace function public.is_course_member(course_id bigint, user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.enrollments e
    where e.course_id = is_course_member.course_id
    and e.user_id = is_course_member.user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if user is a TA of a course
create or replace function public.is_course_ta(course_id bigint, user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.enrollments e
    where e.course_id = is_course_ta.course_id
    and e.user_id = is_course_ta.user_id
    and e.role = 'ta'
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if thread is unlocked
create or replace function public.is_thread_unlocked(thread_id bigint)
returns boolean as $$
begin
  return not exists (
    select 1 from public.threads t
    where t.id = is_thread_unlocked.thread_id
    and t.is_locked = true
  );
end;
$$ language plpgsql security definer;

-- COURSES POLICIES
-- R1: Course members can see their courses
create policy "course_select_members"
  on public.courses
  for select
  to authenticated
  using (
    public.is_course_member(id, auth.uid())
  );

-- R5: Nobody can change courses through the app (no insert/update/delete for authenticated)
-- R6: No anon access
-- R7: service_role bypasses RLS

-- ENROLLMENTS POLICIES
-- R1: Course members can see their own enrollment rows
create policy "enrollment_select_own"
  on public.enrollments
  for select
  to authenticated
  using (
    user_id = auth.uid()
  );

-- R5: Nobody can change enrollments through the app (no insert/update/delete for authenticated)
-- R6: No anon access
-- R7: service_role bypasses RLS

-- THREADS POLICIES
-- R1: Course members can see threads in their courses
create policy "thread_select_members"
  on public.threads
  for select
  to authenticated
  using (
    public.is_course_member(course_id, auth.uid())
  );

-- R2: Course members can start unlocked threads as themselves in their courses
create policy "thread_insert_members"
  on public.threads
  for insert
  to authenticated
  with check (
    public.is_course_member(course_id, auth.uid())
    and created_by = auth.uid()
    and is_locked = false
  );

-- R4: TAs can lock/unlock threads (update is_locked only, but we allow all updates for TAs)
-- Authors cannot update if not TA
create policy "thread_update_tas"
  on public.threads
  for update
  to authenticated
  using (
    public.is_course_ta(course_id, auth.uid())
  )
  with check (
    public.is_course_ta(course_id, auth.uid())
  );

-- R5: No delete through app
-- R6: No anon access
-- R7: service_role bypasses RLS

-- POSTS POLICIES
-- R1: Course members can see posts in their courses (via thread)
create policy "post_select_members"
  on public.posts
  for select
  to authenticated
  using (
    exists (
      select 1 from public.threads t
      where t.id = posts.thread_id
      and public.is_course_member(t.course_id, auth.uid())
    )
  );

-- R2: Course members can write posts as themselves in unlocked threads of their courses
create policy "post_insert_members"
  on public.posts
  for insert
  to authenticated
  with check (
    author_id = auth.uid()
    and public.is_thread_unlocked(thread_id)
    and exists (
      select 1 from public.threads t
      where t.id = posts.thread_id
      and public.is_course_member(t.course_id, auth.uid())
    )
  );

-- R3: Authors can edit their own posts, but only while thread is unlocked
-- R4: TAs can edit any post in their courses (for delete, we use separate policy)
create policy "post_update_authors_or_tas"
  on public.posts
  for update
  to authenticated
  using (
    (
      author_id = auth.uid()
      and public.is_thread_unlocked(thread_id)
    )
    or
    exists (
      select 1 from public.threads t
      where t.id = posts.thread_id
      and public.is_course_ta(t.course_id, auth.uid())
    )
  )
  with check (
    (
      author_id = auth.uid()
      and public.is_thread_unlocked(thread_id)
    )
    or
    exists (
      select 1 from public.threads t
      where t.id = posts.thread_id
      and public.is_course_ta(t.course_id, auth.uid())
    )
  );

-- R3: Authors can delete their own posts, but only while thread is unlocked
-- R4: TAs can delete any post in their courses
create policy "post_delete_authors_or_tas"
  on public.posts
  for delete
  to authenticated
  using (
