```sql
-- Enable RLS on tables
alter table public.items enable row level security;
alter table public.claims enable row level security;

-- Helper function: check if user is service role (bypass helper for readability, though service_role bypasses RLS natively)
create or replace function public.is_service_role()
returns boolean as $$
begin
  return coalesce(current_setting('request.jwt.claims', true)::json->>'role', '') = 'service_role';
end;
$$ language plpgsql security definer;

-- Helper function: check if claim can be approved (no existing approved claim on same item)
create or replace function public.has_no_approved_claim(p_item_id bigint, p_claim_id bigint)
returns boolean as $$
begin
  return not exists (
    select 1 from public.claims
    where item_id = p_item_id
      and id != p_claim_id
      and status = 'approved'
  );
end;
$$ language plpgsql security definer;

-- ============================================
-- ITEMS POLICIES
-- ============================================

-- R1, R5: Anyone can view all items (authenticated users only per R5)
create policy "items_select_authenticated"
  on public.items
  for select
  to authenticated
  using (true);

-- R1: Finders can insert items as themselves
create policy "items_insert_own"
  on public.items
  for insert
  to authenticated
  with check (auth.uid() = found_by);

-- R1: Finders can update their own items
create policy "items_update_own"
  on public.items
  for update
  to authenticated
  using (auth.uid() = found_by)
  with check (auth.uid() = found_by);

-- R6: Service role full access (explicit, though bypasses RLS)
create policy "items_service_role_all"
  on public.items
  for all
  to service_role
  using (true)
  with check (true);

-- ============================================
-- CLAIMS POLICIES
-- ============================================

-- R2: Claimants can see their own claims
-- R2: Finders can see all claims on their items
create policy "claims_select"
  on public.claims
  for select
  to authenticated
  using (
    auth.uid() = claimant_id
    or auth.uid() = (select found_by from public.items where id = item_id)
  );

-- R3: Users can claim open items they did not find, as themselves
create policy "claims_insert"
  on public.claims
  for insert
  to authenticated
  with check (
    auth.uid() = claimant_id
    and exists (
      select 1 from public.items
      where id = item_id
        and status = 'open'
        and found_by != auth.uid()
    )
    and status = 'pending'
  );

-- R4: Only finder can approve/reject pending claim; claimants never change status; nothing else changes
-- Only status can be updated, and only by the finder, and only from 'pending' to 'approved' or 'rejected'
-- Also enforce at most one approved claim per item when approving
create policy "claims_update_finder_only"
  on public.claims
  for update
  to authenticated
  using (
    auth.uid() = (select found_by from public.items where id = claims.item_id)
    and status = 'pending'
  )
  with check (
    auth.uid() = (select found_by from public.items where id = item_id)
    and status in ('approved', 'rejected')
    and (status != 'approved' or public.has_no_approved_claim(item_id, id))
  );

-- R6: Service role full access
create policy "claims_service_role_all"
  on public.claims
  for all
  to service_role
  using (true)
  with check (true);

-- ============================================
-- TRIGGER: Prevent non-status updates on claims (R4 enforcement)
-- ============================================

create or replace function public.claims_update_check()
returns trigger as $$
begin
  -- Only status can change; nothing else about a claim can change
  if old.id != new.id or old.item_id != new.item_id or old.claimant_id != new.claimant_id or old.message != new.message then
    raise exception 'Only status can be updated on claims';
  end if;

  -- Status can only change from pending
  if old.status != 'pending' then
    raise exception 'Can only update pending claims';
  end if;

  -- Status can only go to approved or rejected
  if new.status not in ('approved', 'rejected') then
    raise exception 'Status can only be changed to approved or rejected';
  end if;

  -- Only finder can update
  if auth.uid() != (select found_by from public.items where id = old.item_id) then
    raise exception 'Only the finder can approve or reject claims';
  end if;

  -- At most one approved claim per item
  if new.status = 'approved' and exists (
    select 1 from public.claims 
    where item_id = new.item_id 
      and id != new.id 
      and status = 'approved'
  ) then
    raise exception 'Item already has an approved claim';
  end if;

  return new;
end;
$$ language plpgsql security definer;

create trigger claims_update_trigger
  before update on public.claims
  for each row
  execute function public.claims_update_check();

-- ============================================
-- TRIGGER: Ensure items stay open when claims are pending (optional data integrity)
-- ============================================

create or replace function public.items_status_check()
returns trigger as $$
begin
  -- Items with approved claims can't have new claims (handled by R3 check)
  -- Items can't be set to claimed if they don't have an approved claim
  if new.status = 'claimed' and not exists (
