declare
  new_vehicle_id bigint;
  new_driver_id uuid;
  new_trip_date date;
begin
  -- For UPDATE, use NEW values; for DELETE, we only need ownership check which is separate
  new_vehicle_id := (case when tg_op = 'DELETE' then null else NEW.vehicle_id end);
  new_driver_id := (case when tg_op = 'DELETE' then null else NEW.driver_id end);
  new_trip_date := (case when tg_op = 'DELETE' then null else NEW.trip_date end);

  if tg_op = 'DELETE' then
    return true; -- ownership check done by policy
  end if;

  return public.has_valid_assignment(new_driver_id, new_vehicle_id, new_trip_date);
end;
