  return;
end;
$$ language plpgsql security definer;

-- Recreate view to use the security definer function
-- Actually, better approach: use a regular view and control access via the underlying table
-- But we need agents to see customers too, which violates R1 for the base table
-- So we need a separate table or a different architecture

-- Alternative: Create a separate table for the view that gets updated via trigger
-- But that's complex. Let's use the security definer function approach as the API.

-- Actually, the cleanest approach for Supabase is to use a view with security_barrier
-- and grant appropriate access, but we need to handle the agent access

-- Let's use a materialized approach or accept that we need to modify the underlying access

-- Re-approach: The view will have its own RLS-like behavior via a security definer function
-- But Supabase works best with direct table/view access

-- Final approach: Use a view that references a function, or use RLS on a separate proxy table

-- Actually, the simplest correct approach for Supabase:
-- 1. Keep customers table with strict RLS (supervisors only)
-- 2. Create support_customers as a security definer view that does its own auth checks

drop view if exists public.support_customers cascade;

create view public.support_customers as
select
  c.id,
  c.region,
  c.full_name,
  public.mask_email(c.email) as email_masked,
  public.mask_phone(c.phone) as phone_masked
from public.customers c
where 
  -- Supervisor: see all
  exists (select 1 from public.supervisors where user_id = auth.uid())
  -- Support agent: see own region only
  or (
    exists (select 1 from public.support_agents where user_id = auth.uid() and region = c.region)
  )
  -- Service role bypass handled separately
;

-- Make the view security definer so it can access customers despite RLS
alter view public.support_customers set (security_definer = true);

-- But we need to be careful: security definer runs as view owner, bypassing RLS completely
-- This means service_role will see all, but we need to enforce agent restrictions in the view definition

-- The view definition above already filters by auth, so this is correct
-- However, we need to ensure the functions are executable

-- Grant execute on functions
grant execute on function public.mask_email(text) to authenticated;
grant execute on function public.mask_email(text) to anon;
grant execute on function public.mask_phone(text) to authenticated;
grant execute on function public.mask_phone(text) to anon;
grant execute on function public.get_support_customers() to authenticated;

-- Grants on view
grant select on public.support_customers to authenticated;
grant select on public.support_customers to anon;

-- R5: Ensure anon sees nothing - the view filters by auth.uid() which is null for anon
-- So the exists checks will fail, returning no rows

-- R6: Service role bypasses RLS anyway, so it sees all customers through the view
-- since security_definer bypasses caller's RLS and service_role bypasses all RLS

-- Wait, we need to re-check. Security definer as view owner: if owner is postgres/supabase_admin,
-- then RLS is bypassed. But the view has a WHERE clause checking auth.uid().
-- For service_role, auth.uid() is null typically, but service_role bypasses RLS on base tables too.

-- Actually, service_role doesn't automatically have auth.uid() set to anything specific.
-- We need to handle service_role in the view.

-- Let's check for service_role in JWT
create or replace function public.is_service_role()
returns boolean as $$
begin
  return coalesce(
    current_setting('request.jwt.claims', true)::jsonb->>'role' = 'service_role',
    false
  );
exception when others then
  return false;
end;
$$ language plpgsql stable security definer;

grant execute on function public.is_service_role() to authenticated;
grant execute on function public.is_service_role() to anon;

-- Recreate view with service_role handling
drop view if exists public.support_customers cascade;

create view public.support_customers as
select
  c.id,
  c.region,
  c.full_name,
  public.mask_email(c.email) as email_masked,
  public.mask_phone(c.phone) as phone_masked
from public.customers c
where 
  -- Service role: see all (R6)
  public.is_service_role()
  -- Supervisor: see all (R1)
  or exists (select 1 from public.supervisors where user_id = auth.uid())
  -- Support agent: see own region only (R3)
  or exists (
    select 1 
    from public.support_agents sa 
    where sa.user_id = auth.uid() and sa.region = c.region
  );

alter view public.support_customers set (security_definer = true);

grant select on public.support_customers to authenticated;
grant select on public.support_customers to anon;
grant execute on function public.is_service_role() to authenticated;
grant execute on function public.is_service_role() to anon;

-- R4: Ensure users can see their own rows in agents/supervisors (already done with policies above)

-- Double-check: We need to ensure no one can modify customers/agents/supervisors through the app
-- The policies above already deny all modifications. But let's be explicit with default deny.

-- Ensure no one can insert/update/delete through the view (it doesn't support it anyway)

-- Revoke any potentially dangerous grants
revoke all on public.customers from anon;
revoke all on public.customers from authenticated;
grant select on public.customers to authenticated; -- Only through RLS policy

revoke all on public.support_agents from anon;
revoke all on public.support_agents from authenticated;
grant select on public.support_agents to authenticated; -- Only through RLS policy

revoke all on public.supervisors from anon;
revoke all on public.supervisors from authenticated;
grant select on public.supervisors to authenticated; -- Only through RLS policy

-- Ensure view has proper grants but no modification
revoke all on public.support_customers from anon;
revoke all on public.support_customers from authenticated;
grant select on public.support_customers to authenticated;
grant select on public.support_customers to anon;

-- Additional safety: prevent insert/update/delete on view
create or replace function public.prevent_support_customers_modification()
returns trigger as $$
begin
  raise exception 'Modifications not allowed on support_customers view';
end;
$$ language plpgsql security definer;

-- We can't create triggers on views directly without INSTEAD OF, but we can prevent
-- The view is read-only by nature (has masked computed columns), so this is fine

-- Final verification of all objects
-- Functions
grant execute on function public.mask_email(text) to authenticated, anon;
grant execute on function public.mask_phone(text) to authenticated, anon;
grant execute on function public.is_service_role() to authenticated, anon;

-- RLS is enabled and policies are created
-- Service role bypasses RLS automatically by Supabase design
