-- Trigger to enforce translated_by is set by translators (not reviewers changing status only)
create or replace function public.enforce_segment_update_rules()
returns trigger as $$
begin
  -- Prevent changing source_text
  if new.source_text is distinct from old.source_text then
    raise exception 'source_text cannot be modified';
  end if;

  -- Prevent changing reviewed segments
  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be modified';
  end if;

  -- If user is translator (not reviewer), enforce translated_by = current user
  if public.is_translator(old.project_id, old.lang) 
     and not public.is_reviewer(old.project_id, old.lang)
     and new.status = 'draft' then
    new.translated_by := auth.uid();
  end if;

  -- If user is reviewer, they can update target_text and set status to reviewed
  -- but cannot set back to draft
  if public.is_reviewer(old.project_id, old.lang) then
    if new.status = 'draft' then
      raise exception 'reviewers cannot set status back to draft';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

