    select exists(select 1 from public.current_user_translator_roles(old.project_id, old.lang) where role = 'reviewer') into user_has_reviewer_role;
    select exists(select 1 from public.current_user_translator_roles(old.project_id, old.lang) where role = 'translator') into user_has_translator_role;

    -- If user is translator (and not reviewer), prevent status changes
    if user_has_translator_role and not user_has_reviewer_role then
      if new.status is distinct from old.status then
        raise exception 'Translators cannot change segment status';
      end if;
    end if;

    -- If user is reviewer, allow status change to reviewed only
    if user_has_reviewer_role then
      if new.status is distinct from old.status and new.status != 'reviewed' then
        raise exception 'Reviewers can only set status to reviewed';
      end if;
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

