-- More restrictive update: translators can only update target_text and translated_by on draft segments
-- Reviewers can update target_text, translated_by, and status to 'reviewed'

-- Trigger to enforce business rules on segment updates
create or replace function public.enforce_segment_update_rules()
returns trigger as $$
declare
  user_roles text[];
  is_rev boolean;
  is_trans boolean;
begin
  -- Skip for service role
  if auth.role() = 'service_role' then
    return new;
  end if;

  -- Must be authenticated
  if not public.is_authenticated() then
    raise exception 'Anonymous users cannot modify segments';
  end if;

  -- Cannot modify if already reviewed (R4)
  if old.status = 'reviewed' then
    raise exception 'Reviewed segments cannot be modified';
  end if;

  -- Must be draft
  if old.status != 'draft' then
    raise exception 'Only draft segments can be modified';
  end if;

  -- Get user's roles for this project/language
  user_roles := public.get_user_translator_roles(old.project_id, old.lang);
  is_rev := 'reviewer' = any(user_roles);
  is_trans := 'translator' = any(user_roles);

  -- Must have some role
  if not is_rev and not is_trans then
    raise exception 'User not assigned to this project/language';
  end if;

  -- Cannot change source_text (R4)
  if new.source_text is distinct from old.source_text then
    raise exception 'source_text cannot be modified';
  end if;

  -- Cannot change project_id or lang
  if new.project_id is distinct from old.project_id or new.lang is distinct from old.lang then
    raise exception 'project_id and lang cannot be modified';
  end if;

  -- Cannot change id
  if new.id is distinct from old.id then
    raise exception 'id cannot be modified';
  end if;

  -- Translator-only cannot set status to reviewed (R3)
  if is_trans and not is_rev then
    if new.status = 'reviewed' then
      raise exception 'Translators cannot mark segments as reviewed';
    end if;
    -- Translators can only update target_text and translated_by, keeping status as draft
    if new.status is distinct from 'draft' then
      raise exception 'Translators must keep status as draft';
    end if;
  end if;

  -- Reviewer can mark as reviewed, but must ensure other fields are valid
  -- If reviewer is changing status to reviewed, that's allowed
  -- If reviewer is keeping as draft, that's also allowed (corrections)

  -- Always set translated_by to current user when target_text changes
  if new.target_text is distinct from old.target_text then
    new.translated_by := auth.uid();
  end if;

  return new;
end;
$$ language plpgsql security definer;

