create or replace function public.check_segment_update()
returns trigger as $$
begin
  -- Prevent changing source_text
  if old.source_text is distinct from new.source_text then
    raise exception 'source_text cannot be modified';
  end if;

  -- Prevent changing project_id or lang
  if old.project_id is distinct from new.project_id then
    raise exception 'project_id cannot be modified';
  end if;
  if old.lang is distinct from new.lang then
    raise exception 'lang cannot be modified';
  end if;

  -- If translator is updating (not reviewer), must set translated_by to self
  if public.is_translator(old.project_id, old.lang) 
     and not public.is_reviewer(old.project_id, old.lang)
     and new.translated_by is distinct from auth.uid() then
    raise exception 'translators must set translated_by to themselves';
  end if;

  -- If reviewer is updating, they can correct translation but must mark reviewed
  if public.is_reviewer(old.project_id, old.lang) 
     and old.status = 'draft' 
     and new.status = 'reviewed' then
    -- Allow: reviewer approving (and optionally correcting target_text)
    null;
  elsif public.is_translator(old.project_id, old.lang) 
        and old.status = 'draft' 
        and new.status = 'draft' then
    -- Allow: translator saving draft
    null;
  elsif old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be modified';
  end if;

  return new;
end;
$$ language plpgsql security definer;

