      raise exception 'Child cannot modify chore details';
    end if;
  end if;

  -- Parent approval: can change status to approved, but not other fields when approving
  if public.is_parent_in_household(old.household_id, auth.uid()) then
    if old.status = 'approved' then
      raise exception 'Approved chores cannot be modified';
    end if;
  end if;

  return new;
end;
$$;

