  user_role text;
begin
  -- Get the user's role in this household
  user_role := public.get_household_role(new.household_id);

  -- If user is a child, enforce strict rules
  if user_role = 'child' then
    -- Child can only update their own assigned chores
    if old.assignee_id != auth.uid() then
      raise exception 'Children can only update their own chores';
    end if;

    -- Child can only change status from todo to done
    if old.status != 'todo' or new.status != 'done' then
      raise exception 'Children can only mark todo chores as done';
    end if;

    -- Child cannot change any other fields
    if old.title != new.title 
       or old.points != new.points 
       or old.assignee_id != new.assignee_id
       or old.household_id != new.household_id then
      raise exception 'Children cannot change chore title, points, assignee, or household';
    end if;
  end if;

  -- If user is parent, they cannot modify approved chores
  if user_role = 'parent' and old.status = 'approved' then
    raise exception 'Approved chores cannot be modified';
  end if;

  -- Parents can approve (change to approved), but let's also prevent children from doing so
  if new.status = 'approved' and user_role != 'parent' then
    raise exception 'Only parents can approve chores';
  end if;

  return new;
end;
$$;

