  end if;

  -- Get user's role in the household
  v_user_role := public.get_household_role(old.household_id);

  -- If not a child, let other policies handle it
  if v_user_role != 'child' then
    return new;
  end if;

  -- Child can only update their own chores
  if old.assignee_id != auth.uid() then
    raise exception 'Children can only update their own chores';
  end if;

  -- Child can only mark todo as done
  if old.status != 'todo' then
    raise exception 'Children can only update todo chores';
  end if;

  -- Child can only change status to done
  if new.status != 'done' then
    raise exception 'Children can only mark chores as done';
  end if;

  -- Child cannot change any other fields
  if new.title != old.title or 
     new.points != old.points or 
     new.assignee_id != old.assignee_id or 
     new.household_id != old.household_id or
     new.id != old.id then
    raise exception 'Children can only change status to done';
  end if;

  return new;
end;
$$;

