set search_path = public
as $$
declare
  user_role text;
begin
  -- Skip for service role
  if auth.role() = 'service_role' then
    return new;
  end if;

  -- Get user's role in the org
  select role into user_role
  from public.org_members
  where org_id = new.org_id and user_id = auth.uid();

  -- No membership = deny
  if user_role is null then
    raise exception 'Not a member of this organization';
  end if;

  -- Developers cannot create/update prod flags
  if user_role = 'developer' and new.env = 'prod' then
    raise exception 'Developers cannot create or modify production flags';
  end if;

  -- Admins can do anything with their org's flags
  if user_role = 'admin' then
    return new;
  end if;

  -- Developers can only work with dev
  if user_role = 'developer' and new.env = 'dev' then
    return new;
  end if;

  raise exception 'Unauthorized flag operation';
end;
$$;

