-- Create the place_bid function
create or replace function public.place_bid(
  p_auction_id bigint,
  p_amount numeric
)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction record;
  v_min_bid numeric;
  v_new_highest numeric;
begin
  -- Check caller is signed in
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;

  -- Lock and get auction
  select *
  into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  -- Check auction exists
  if v_auction is null then
    raise exception 'Auction does not exist';
  end if;

  -- Check auction has not ended
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- Check caller is not the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Seller cannot bid on their own auction';
  end if;

  -- Calculate minimum bid
  if v_auction.highest_bid is null then
    v_min_bid := v_auction.starting_price;
  else
    v_min_bid := v_auction.highest_bid + v_auction.min_increment;
  end if;

  -- Check amount is sufficient
  if p_amount < v_min_bid then
    raise exception 'Bid amount too low. Minimum required: %', v_min_bid;
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update auction with new highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end;
$$;

-- Grant execute on function to authenticated users only
