create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction record;
  v_new_highest numeric;
begin
  -- R4: Must be signed in
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;

