  -- R4: Auction must not have ended
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- R4: Caller cannot be the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Seller cannot bid on their own auction';
  end if;

  -- R4: Validate bid amount
  if v_auction.highest_bid is null then
    -- No bids yet: must be at least starting price
    if p_amount < v_auction.starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
    v_new_highest := p_amount;
  else
    -- Must beat highest bid by at least min_increment
    if p_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'Bid must be at least % higher than current highest bid', v_auction.min_increment;
    end if;
    v_new_highest := p_amount;
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update auction with new highest bid
  update public.auctions
  set highest_bid = v_new_highest,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return v_new_highest;
end;
$$;

