-- (achieved by not granting any permissions to anon)

-- Helper function: check if caller can sign
create or replace function public.can_sign_envelope(p_envelope_id bigint, p_user_id uuid)
returns boolean
language plpgsql
security definer
as $$
declare
  v_status text;
  v_sign_order integer;
  v_max_signed_order integer;
begin
  -- Check envelope status
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null or v_status != 'sent' then
    return false;
  end if;

  -- Check caller is a recipient and hasn't signed
  select sign_order into v_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = p_user_id and signed_at is null;

  if v_sign_order is null then
    return false;
  end if;

  -- Check all earlier signers have signed
  select coalesce(max(sign_order), 0) into v_max_signed_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if v_max_signed_order + 1 != v_sign_order then
    return false;
  end if;

  return true;
end;
$$;

-- R3: sign_envelope function
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_user_id uuid;
  v_status text;
  v_unsigned_count integer;
begin
  v_user_id := auth.uid();

  -- Validate caller can sign
  if not public.can_sign_envelope(p_envelope_id, v_user_id) then
    raise exception 'Cannot sign: not a valid recipient, already signed, envelope not sent, or earlier signers have not signed';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed
  select count(*) into v_unsigned_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is null;

  if v_unsigned_count = 0 then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$;

-- R4: void_envelope function
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_sender_id uuid;
  v_status text;
begin
  -- Get envelope info
  select sender_id, status into v_sender_id, v_status
  from public.envelopes
  where id = p_envelope_id;

  -- Validate: must be sender and status must be 'sent'
  if v_sender_id is null then
    raise exception 'Envelope not found';
  end if;

  if v_sender_id != auth.uid() then
    raise exception 'Only the sender can void an envelope';
  end if;

  if v_status != 'sent' then
    raise exception 'Can only void envelopes with status ''sent''';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

-- Grant execute on functions to authenticated users
grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;

-- Ensure service_role has full access (R6)
grant all on public.envelopes to service_role;
grant all on public.envelope_recipients to service_role;
grant execute on function public.sign_envelope(bigint) to service_role;
grant execute on function public.void_envelope(bigint) to service_role;
