  v_status text;
  v_my_sign_order integer;
  v_my_signed_at timestamptz;
  v_max_unsigned_order integer;
begin
  v_user_id := auth.uid();

  -- Check envelope exists and is sent
  select status into v_status
  from public.envelopes
  where id = p_envelope_id;

  if v_status is null then
    raise exception 'Envelope not found';
  end if;

