    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if v_my_signed_at is not null then
    raise exception 'Recipient has already signed';
  end if;

  -- Check all earlier sign_orders have signed
  select max(sign_order) into v_max_unsigned_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is null
    and sign_order < v_my_sign_order;

  if v_max_unsigned_order is not null then
    raise exception 'Earlier recipient has not signed yet';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed, if so complete the envelope
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and signed_at is null
  ) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  end if;

  return 'sent';
end;
