-- R3: sign_envelope function
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_envelope_status text;
  v_caller_recipient record;
  v_unsigned_before record;
begin
  v_user_id := auth.uid();

  -- Check envelope exists and is sent
  select status into v_envelope_status
  from public.envelopes
  where id = p_envelope_id;

  if v_envelope_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not sent';
  end if;

  -- Check caller is a recipient
  select * into v_caller_recipient
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_user_id;

  if v_caller_recipient is null then
    raise exception 'Caller is not a recipient';
  end if;

  -- Check caller hasn't already signed
  if v_caller_recipient.signed_at is not null then
    raise exception 'Caller has already signed';
  end if;

  -- Check all earlier signers have signed
  select * into v_unsigned_before
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and sign_order < v_caller_recipient.sign_order
    and signed_at is null
  limit 1;

  if v_unsigned_before is not null then
    raise exception 'Earlier recipients have not signed yet';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed, mark completed if so
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and signed_at is null
  ) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  end if;

  return 'sent';
end;
$$;

-- R4: void_envelope function
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_envelope record;
begin
  v_user_id := auth.uid();

  -- Check envelope exists and get details
  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id;

  if v_envelope is null then
    raise exception 'Envelope not found';
  end if;

  -- Only sender can void
  if v_envelope.sender_id != v_user_id then
    raise exception 'Only sender can void envelope';
  end if;

  -- Only sent envelopes can be voided
  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not sent';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

