  select status into v_envelope_status
  from public.envelopes
  where id = p_envelope_id;

  if v_envelope_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Get caller's recipient info
  select 
    (signed_at is not null),
    sign_order
  into 
    v_caller_signed_at,
    v_caller_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = auth.uid();

  v_caller_is_recipient := found;

  if not v_caller_is_recipient then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if v_caller_signed_at is not null then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- Check if any earlier sign_order recipient hasn't signed
  select exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
      and sign_order < v_caller_sign_order
      and signed_at is null
  ) into v_unsigned_earlier_exists;

  if v_unsigned_earlier_exists then
    raise exception 'An earlier recipient has not yet signed';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  -- Check if all recipients have signed, if so complete the envelope
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and signed_at is null
  ) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  end if;

  return 'sent';
end;
$$ language plpgsql security definer;

