returns text
language plpgsql
security definer
as $$
declare
  v_user_id uuid;
  v_envelope_status text;
  v_sign_order integer;
  v_max_completed_order integer;
  v_recipient_count integer;
  v_signed_count integer;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select status into v_envelope_status
  from public.envelopes
  where id = p_envelope_id
  for update;

  if v_envelope_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_envelope_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  select er.sign_order into v_sign_order
  from public.envelope_recipients er
  where er.envelope_id = p_envelope_id
    and er.user_id = v_user_id;

  if v_sign_order is null then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = v_user_id
      and signed_at is not null
  ) then
    raise exception 'Recipient has already signed';
  end if;

  select coalesce(max(sign_order), 0) into v_max_completed_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is not null;

  if v_sign_order > v_max_completed_order + 1 then
    raise exception 'Previous recipient in sign order has not signed yet';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_user_id;

  select count(*) into v_recipient_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is not null;

  if v_signed_count = v_recipient_count then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  end if;

  return 'sent';
end;
$$;

