create or replace function public.enforce_customer_approval()
returns trigger as $$
begin
  -- Only apply when customer is changing quoted -> approved
  if old.status = 'quoted' and new.status = 'approved' and old.customer_id = auth.uid() then
    -- Ensure garage_id, customer_id, vehicle, quote_amount are unchanged
    if new.garage_id is distinct from old.garage_id or
       new.customer_id is distinct from old.customer_id or
       new.vehicle is distinct from old.vehicle or
       new.quote_amount is distinct from old.quote_amount then
      raise exception 'Customer approval cannot modify garage_id, customer_id, vehicle, or quote_amount';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

