returns trigger as $$
begin
  -- Prevent mechanics from changing status to approved
  if old.status = 'quoted' and new.status = 'approved' and public.is_mechanic_for_garage(old.garage_id) then
    -- Check if this is a mechanic (not the customer)
    if old.customer_id != auth.uid() then
      raise exception 'Mechanics cannot approve jobs on behalf of customers';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

