returns trigger as $$
begin
  -- When mechanic updates approved/in_progress -> in_progress/done
  if old.status in ('approved', 'in_progress') and new.status in ('in_progress', 'done') and
     public.is_mechanic_for_garage(old.garage_id) and old.customer_id != auth.uid() then
    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'Mechanics cannot change quote amount when updating job progress';
    end if;
  end if;
  return new;
end;
