-- Enable RLS on all tables
alter table public.garages enable row level security;
alter table public.mechanics enable row level security;
alter table public.jobs enable row level security;

-- Helper functions
create or replace function public.is_mechanic_of_garage(gid bigint)
returns boolean as $$
  select exists (
    select 1 from public.mechanics
    where garage_id = gid and user_id = auth.uid()
  );
$$ language sql security definer;

create or replace function public.is_customer_of_job(jid bigint)
returns boolean as $$
  select exists (
    select 1 from public.jobs
    where id = jid and customer_id = auth.uid()
  );
$$ language sql security definer;

create or replace function public.get_job_garage_id(jid bigint)
returns bigint as $$
  select garage_id from public.jobs where id = jid;
$$ language sql security definer;

create or replace function public.get_job_status(jid bigint)
returns text as $$
  select status from public.jobs where id = jid;
$$ language sql security definer;

-- Validate job updates based on status transitions
create or replace function public.validate_job_update()
returns trigger as $$
declare
  old_status text;
  new_status text;
  is_mechanic boolean;
  is_customer boolean;
begin
  old_status := old.status;
  new_status := new.status;
  is_mechanic := public.is_mechanic_of_garage(old.garage_id);
  is_customer := (old.customer_id = auth.uid());

  -- R5: prevent changing garage_id or customer_id
  if new.garage_id is distinct from old.garage_id then
    raise exception 'Cannot change garage_id';
  end if;
  if new.customer_id is distinct from old.customer_id then
    raise exception 'Cannot change customer_id';
  end if;

  -- Customer approving: quoted -> approved
  if old_status = 'quoted' and new_status = 'approved' then
    if not is_customer then
      raise exception 'Only customer can approve';
    end if;
    -- R3: cannot change anything else when approving
    if new.vehicle is distinct from old.vehicle then
      raise exception 'Cannot change vehicle when approving';
    end if;
    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'Cannot change quote_amount when approving';
    end if;
    return new;
  end if;

  -- Mechanic operations
  if is_mechanic then
    -- R2: mechanic can update while quoted (change quote, stay quoted)
    if old_status = 'quoted' and new_status = 'quoted' then
      -- Allow vehicle and quote_amount changes, but not customer_id or garage_id (already checked)
      return new;
    end if;

    -- R4: approved -> in_progress
    if old_status = 'approved' and new_status = 'in_progress' then
      if new.quote_amount is distinct from old.quote_amount then
        raise exception 'Cannot change quote_amount when moving to in_progress';
      end if;
      if new.vehicle is distinct from old.vehicle then
        raise exception 'Cannot change vehicle when moving to in_progress';
      end if;
      return new;
    end if;

    -- R4: in_progress -> done
    if old_status = 'in_progress' and new_status = 'done' then
      if new.quote_amount is distinct from old.quote_amount then
        raise exception 'Cannot change quote_amount when moving to done';
      end if;
      if new.vehicle is distinct from old.vehicle then
        raise exception 'Cannot change vehicle when moving to done';
      end if;
      return new;
    end if;
  end if;

  -- Any other transition is invalid
  raise exception 'Invalid status transition from % to %', old_status, new_status;
end;
$$ language plpgsql security definer;

-- Trigger for job updates
create trigger jobs_update_validation
  before update on public.jobs
  for each row
  execute function public.validate_job_update();

-- Garages policies
create policy "garages_select_authenticated"
  on public.garages
  for select
  to authenticated
  using (true);

-- Mechanics policies
create policy "mechanics_select_authenticated"
  on public.mechanics
  for select
  to authenticated
  using (true);

-- Jobs policies
create policy "jobs_select_authenticated"
  on public.jobs
  for select
  to authenticated
  using (
    customer_id = auth.uid()
    or public.is_mechanic_of_garage(garage_id)
  );

create policy "jobs_insert_mechanic"
  on public.jobs
  for insert
  to authenticated
  with check (
    public.is_mechanic_of_garage(garage_id)
    and status = 'quoted'
  );

create policy "jobs_update_authenticated"
  on public.jobs
  for update
  to authenticated
  using (
    customer_id = auth.uid()
    or public.is_mechanic_of_garage(garage_id)
  )
  with check (
    customer_id = auth.uid()
    or public.is_mechanic_of_garage(garage_id)
  );

-- R5: no delete policy means deletes are denied for non-service_role

-- Service role bypass (handled by Supabase automatically, but explicit grants ensure)
grant all on public.garages to service_role;
grant all on public.mechanics to service_role;
grant all on public.jobs to service_role;

-- Ensure authenticated role has appropriate usage
grant select on public.garages to authenticated;
grant select on public.mechanics to authenticated;
grant select, insert, update on public.jobs to authenticated;

-- Revoke delete on jobs from authenticated to be explicit
revoke delete on public.jobs from authenticated;
