  -- Get desk zone
  select zone into v_zone from public.desks where id = p_desk_id;
  if v_zone is null then
    return false;
  end if;

  -- Get membership info
  select tier, valid_until into v_tier, v_valid_until
  from public.memberships
  where user_id = p_user_id;

