$$ language plpgsql security definer;

-- Helper function: check if user can book a specific desk on a specific day
create or replace function public.can_book_desk(p_user_id uuid, p_desk_id bigint, p_day date)
returns boolean as $$
declare
  v_membership_tier text;
  v_valid_until date;
  v_desk_zone text;
  v_upcoming_count int;
begin
  -- Get membership info
  select tier, valid_until into v_membership_tier, v_valid_until
  from public.memberships
  where user_id = p_user_id;

  -- Must have valid membership
  if v_membership_tier is null or v_valid_until < p_day then
    return false;
  end if;

  -- Day must be today or later
  if p_day < current_date then
    return false;
  end if;

  -- Get desk zone
  select zone into v_desk_zone from public.desks where id = p_desk_id;

  -- Premium desks require premium membership
  if v_desk_zone = 'premium' and v_membership_tier != 'premium' then
    return false;
  end if;

  -- Check upcoming booking count (today or later, excluding the day being booked if already counted)
  select count(*) into v_upcoming_count
  from public.bookings
  where user_id = p_user_id
    and day >= current_date;

  -- Allow if under 3 upcoming bookings (the insert will make it 3, so must be < 3 currently)
  return v_upcoming_count < 3;
end;
