alter table public.editors enable row level security;

-- Helper function to check if current user is an editor
create or replace function public.is_editor(check_user_id uuid default auth.uid())
returns boolean as $$
begin
  return exists (
    select 1 from public.editors where user_id = check_user_id
  );
end;
$$ language plpgsql security definer;

-- R5: Users can see whether they themselves are an editor. Nobody can change editors through the app.
create policy "editors_select_own"
  on public.editors
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "editors_no_insert"
  on public.editors
  for insert
  to authenticated
  with check (false);

create policy "editors_no_update"
  on public.editors
  for update
  to authenticated
  using (false);

create policy "editors_no_delete"
  on public.editors
  for delete
  to authenticated
  using (false);

-- R1: Anyone can read published articles. Writers can read their own. Editors can read all.
create policy "articles_select"
  on public.articles
  for select
  to anon, authenticated
  using (
    status = 'published'
    or author_id = auth.uid()
    or public.is_editor()
  );

-- R2: Writers can create drafts as themselves
create policy "articles_insert"
  on public.articles
  for insert
  to authenticated
  with check (
    author_id = auth.uid()
    and status = 'draft'
  );

-- R2: Writers can edit their own drafts and submit for review. R3: Editors can edit in_review articles.
-- R4: Published articles cannot be changed.
create policy "articles_update"
  on public.articles
  for update
  to authenticated
  using (
    -- Writers can update their own drafts
    (author_id = auth.uid() and status = 'draft')
    -- Editors can update in_review articles
    or (public.is_editor() and status = 'in_review')
  )
  with check (
    -- Writers: must remain draft or become in_review, cannot publish
    (
      author_id = auth.uid()
      and status in ('draft', 'in_review')
      and published_at is null
    )
    -- Editors: can set to published (with published_at) or back to draft
    or (
      public.is_editor()
      and status in ('draft', 'published')
      and (status = 'draft' or published_at is not null)
    )
  );

-- R4: Writers can delete only their own drafts
create policy "articles_delete"
  on public.articles
  for delete
  to authenticated
  using (
    author_id = auth.uid()
    and status = 'draft'
  );

-- Prevent non-service-role from modifying editors
revoke all on public.editors from anon, authenticated;
grant select on public.editors to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants for safety)
grant all on public.articles to service_role;
grant all on public.editors to service_role;
