-- R1: Read access - published for anyone, own for writers, all for editors
create policy "articles_select_anon"
  on public.articles
  for select
  to anon
  using (status = 'published');

create policy "articles_select_authenticated"
  on public.articles
  for select
  to authenticated
  using (
    status = 'published'
    or author_id = auth.uid()
    or public.is_editor()
  );

create policy "articles_select_service"
  on public.articles
  for select
  to service_role
  using (true);

-- R2: Writers can create drafts as themselves
create policy "articles_insert_writer"
  on public.articles
  for insert
  to authenticated
  with check (
    author_id = auth.uid()
    and status = 'draft'
  );

create policy "articles_insert_service"
  on public.articles
  for insert
  to service_role
  with check (true);

-- R2: Writers can edit their own drafts, submit for review
-- R3: Editors can edit in_review articles
create policy "articles_update_writer_draft"
  on public.articles
  for update
  to authenticated
  using (
    -- Writers can only update their own drafts
    (author_id = auth.uid() and status = 'draft')
    -- Editors can update in_review articles
    or (public.is_editor() and status = 'in_review')
  )
  with check (
    -- Writers: must remain draft or go to in_review, cannot change author
    (
      author_id = auth.uid()
      and status in ('draft', 'in_review')
      and (select status from public.articles where id = articles.id) = 'draft'
    )
    -- Editors: must remain in_review or go to draft/published, cannot change author
    or (
      public.is_editor()
      and status in ('draft', 'in_review', 'published')
      and (select status from public.articles where id = articles.id) = 'in_review'
    )
  );

create policy "articles_update_service"
  on public.articles
  for update
  to service_role
  using (true)
  with check (true);

-- R4: Writers can delete only their own drafts
create policy "articles_delete_writer_draft"
  on public.articles
  for delete
  to authenticated
  using (author_id = auth.uid() and status = 'draft');

create policy "articles_delete_service"
  on public.articles
  for delete
  to service_role
  using (true);

-- Additional policy to prevent updates to published articles (R4)
-- This is enforced by the update policies above, but we add a trigger for extra safety
create or replace function public.prevent_published_update()
returns trigger as $$
begin
  if old.status = 'published' then
    raise exception 'Published articles cannot be modified';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger prevent_published_update_trigger
  before update on public.articles
  for each row
  execute function public.prevent_published_update();

-- Prevent writers from changing author_id
create or replace function public.prevent_author_change()
returns trigger as $$
begin
  if old.author_id is distinct from new.author_id then
    raise exception 'Cannot change article author';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger prevent_author_change_trigger
  before update on public.articles
  for each row
  execute function public.prevent_author_change();

-- Prevent editors from modifying drafts or published articles via trigger
create or replace function public.editor_update_restrictions()
returns trigger as $$
begin
  if public.is_editor() then
    -- Editor updating: old status must be in_review
    if old.status <> 'in_review' then
      raise exception 'Editors can only modify articles that are in_review';
    end if;
    -- Editor can set to draft or published
    if new.status not in ('draft', 'published', 'in_review') then
      raise exception 'Editors can only set status to draft, published, or keep in_review';
    end if;
  else
    -- Writer updating: old status must be draft, new status must be draft or in_review
    if old.status <> 'draft' then
      raise exception 'Writers can only modify their own drafts';
    end if;
    if new.status not in ('draft', 'in_review') then
      raise exception 'Writers can only set status to draft or in_review';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger editor_update_restrictions_trigger
  before update on public.articles
  for each row
  execute function public.editor_update_restrictions();

-- Prevent non-service-role from modifying editors table
create policy "editors_no_insert"
  on public.editors
  for all
  to authenticated
  using (false)
  with check (false);

-- Revoke default privileges and set proper grants
revoke all on public.articles from anon, authenticated;
revoke all on public.editors from anon, authenticated;

grant select on public.articles to anon;
grant select, insert, update, delete on public.articles to authenticated;
grant select on public.editors to authenticated;

-- Ensure service_role has full access
grant all on public.articles to service_role;
grant all on public.editors to service_role;

-- Allow authenticated users to execute helper function
grant execute on function public.is_editor(uuid) to authenticated;
