returns boolean as $$
begin
  return exists (
    select 1 from public.org_admins
    where org_id = check_org_id and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if current user is an admin of a device's org
create or replace function public.is_device_org_admin(check_device_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.devices d
    join public.org_admins oa on d.org_id = oa.org_id
    where d.id = check_device_id and oa.user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

