alter table public.household_members enable row level security;
alter table public.shopping_items enable row level security;

-- Helper function: check if current user is a member of a household
create or replace function public.is_household_member(p_household_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.household_members
    where household_id = p_household_id
    and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if current user is a member of a household for a given item
create or replace function public.is_item_household_member(p_item_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.shopping_items si
    join public.household_members hm on si.household_id = hm.household_id
    where si.id = p_item_id
    and hm.user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Household members policies
create policy "R1: Members can see their household's members"
  on public.household_members
  for select
  to authenticated
  using (user_id = auth.uid() or exists (
    select 1 from public.household_members hm2
    where hm2.household_id = household_members.household_id
    and hm2.user_id = auth.uid()
  ));

create policy "No anon access to household_members"
  on public.household_members
  for all
  to anon
  using (false)
  with check (false);

-- Shopping items policies
create policy "R1: Members can see their household's items"
  on public.shopping_items
  for select
  to authenticated
  using (public.is_household_member(household_id));

create policy "R2: Members can add items to their household as themselves"
  on public.shopping_items
  for insert
  to authenticated
  with check (
    public.is_household_member(household_id)
    and added_by = auth.uid()
    and claimed_by is null
    and is_bought = false
  );

create policy "R3: Members can claim/unclaim items, R4: Only claimant can mark bought"
  on public.shopping_items
  for update
  to authenticated
  using (public.is_item_household_member(id))
  with check (
    public.is_household_member(household_id)
    -- Only these fields can change: claimed_by, is_bought
    -- name, household_id, added_by must remain unchanged
    and name = (select name from shopping_items where id = shopping_items.id)
    and household_id = (select household_id from shopping_items where id = shopping_items.id)
    and added_by = (select added_by from shopping_items where id = shopping_items.id)
    -- claimed_by rules: can claim unclaimed item, unclaim own, or keep same
    and (
      -- claiming an unclaimed item
      ((select claimed_by from shopping_items where id = shopping_items.id) is null and claimed_by = auth.uid())
      -- unclaiming own item
      or ((select claimed_by from shopping_items where id = shopping_items.id) = auth.uid() and claimed_by is null)
      -- keeping same claimed_by
      or (claimed_by = (select claimed_by from shopping_items where id = shopping_items.id))
    )
    -- is_bought rules: only claimant can mark bought, and bought stays claimed
    and (
      -- not changing is_bought
      is_bought = (select is_bought from shopping_items where id = shopping_items.id)
      -- marking bought: must be claimed by current user, and stays claimed
      or (
        (select claimed_by from shopping_items where id = shopping_items.id) = auth.uid()
        and is_bought = true
        and claimed_by = (select claimed_by from shopping_items where id = shopping_items.id)
        and (select is_bought from shopping_items where id = shopping_items.id) = false
      )
    )
  );

create policy "R5: Added_by can delete if not bought"
  on public.shopping_items
  for delete
  to authenticated
  using (
    added_by = auth.uid()
    and is_bought = false
    and public.is_item_household_member(id)
  );

create policy "No anon access to shopping_items"
  on public.shopping_items
  for all
  to anon
  using (false)
  with check (false);

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
