create policy "shopping_items_insert"
  on public.shopping_items
  for insert
  to authenticated
  with check (
    public.is_household_member(household_id)
    and added_by = auth.uid()
    and claimed_by is null
    and is_bought = false
  );

-- R3, R4: Members can claim/unclaim, only claimed-by can mark bought. Nothing else changes.
-- We enforce this via a trigger instead of policy to handle complex update logic

create or replace function public.shopping_items_update_check()
returns trigger as $$
declare
  v_user uuid := auth.uid();
begin
  -- Must be household member
  if not public.is_household_member(old.household_id) then
    raise exception 'Not a household member';
  end if;

  -- Cannot change household_id, id, added_by, name
  if NEW.household_id is distinct from old.household_id
     or NEW.id is distinct from old.id
     or NEW.added_by is distinct from old.added_by
     or NEW.name is distinct from old.name then
    raise exception 'Cannot change household_id, id, added_by, or name';
  end if;

  -- If marking bought or changing bought status
  if NEW.is_bought is distinct from old.is_bought then
    -- Can only mark bought (true), not unmark
    if NEW.is_bought = false then
      raise exception 'Cannot unmark bought';
    end if;
    -- Must be the one who claimed it
    if old.claimed_by is null or old.claimed_by != v_user then
      raise exception 'Only the claimant can mark bought';
    end if;
    -- Must stay claimed by same person
    if NEW.claimed_by is distinct from old.claimed_by then
      raise exception 'Bought item must stay claimed';
    end if;
    return NEW;
  end if;

  -- If not changing bought status, only claimed_by may change
  if NEW.is_bought = old.is_bought then
    -- If item is already bought, nothing can change
    if old.is_bought = true then
      raise exception 'Cannot modify bought item';
    end if;

    -- Only claimed_by can change
    if NEW.claimed_by is distinct from old.claimed_by then
      -- Claiming: must be unclaimed, claiming as self
      if old.claimed_by is null and NEW.claimed_by = v_user then
        return NEW;
      end if;
      -- Unclaiming: must be claimed by self, setting to null
      if old.claimed_by = v_user and NEW.claimed_by is null then
        return NEW;
      end if;
      raise exception 'Invalid claim operation';
    end if;

    -- No actual change or invalid change
    if NEW.claimed_by is not distinct from old.claimed_by then
      -- No meaningful change allowed (or same values)
      return NEW;
    end if;
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

