-- Redeem referral function
create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
as $$
declare
  v_caller_id uuid;
  v_referrer_id uuid;
  v_referral_id bigint;
  v_referrer_count bigint;
begin
  -- Get caller ID, must be authenticated
  v_caller_id := auth.uid();

  if v_caller_id is null then
    raise exception 'Caller must be signed in';
  end if;

  -- Get the referrer ID from the code
  select user_id into v_referrer_id
  from public.referral_codes
  where code = p_code;

  -- Check code exists
  if v_referrer_id is null then
    raise exception 'Referral code does not exist';
  end if;

  -- Check not redeeming own code
  if v_referrer_id = v_caller_id then
    raise exception 'Cannot redeem your own referral code';
  end if;

  -- Check caller hasn't already redeemed a code
  if public.has_redeemed_referral(v_caller_id) then
    raise exception 'You have already redeemed a referral code';
  end if;

  -- Check referrer hasn't already made 5 referrals
  select count(*) into v_referrer_count
  from public.referrals
  where referrer_id = v_referrer_id;

  if v_referrer_count >= 5 then
    raise exception 'Referrer has reached maximum number of referrals';
  end if;

  -- Insert the referral
  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_referrer_id, v_caller_id, now())
  returning id into v_referral_id;

  -- Give credits to referrer
  insert into public.credits (user_id, amount, reason)
  values (v_referrer_id, 100, 'referral bonus');

  -- Give credits to referee (caller)
  insert into public.credits (user_id, amount, reason)
  values (v_caller_id, 100, 'referral signup bonus');

  return v_referral_id;
end;
$$;

