-- Helper function to check if user has already redeemed a referral
create or replace function public.has_redeemed_referral(p_user_id uuid)
returns boolean
language plpgsql
security definer
as $$
begin
  return exists(
    select 1 from public.referrals
    where referee_id = p_user_id
  );
end;
$$;

-- Helper function to count referrals made by a user
create or replace function public.count_referrals_made(p_user_id uuid)
returns integer
language plpgsql
security definer
as $$
begin
  return (
    select count(*)::integer from public.referrals
    where referrer_id = p_user_id
  );
end;
$$;

-- redeem_referral function
create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
as $$
declare
  v_caller_id uuid;
  v_referrer_id uuid;
  v_referral_id bigint;
begin
  -- Get caller ID, must be authenticated
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'Caller must be signed in';
  end if;

  -- Get referrer ID from code
  select user_id into v_referrer_id
  from public.referral_codes
  where code = p_code;

  -- Check code exists
  if v_referrer_id is null then
    raise exception 'Referral code does not exist';
  end if;

  -- Check not using own code
  if v_referrer_id = v_caller_id then
    raise exception 'Cannot redeem your own referral code';
  end if;

  -- Check caller hasn't already redeemed
  if public.has_redeemed_referral(v_caller_id) then
    raise exception 'Caller has already redeemed a referral code';
  end if;

  -- Check referrer doesn't already have 5 referrals
  if public.count_referrals_made(v_referrer_id) >= 5 then
    raise exception 'Referrer has reached maximum referrals';
  end if;

  -- Insert referral
  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_referrer_id, v_caller_id, now())
  returning id into v_referral_id;

  -- Give credits to referee (caller)
  insert into public.credits (user_id, amount, reason)
  values (v_caller_id, 100, 'referral redemption');

  -- Give credits to referrer
  insert into public.credits (user_id, amount, reason)
  values (v_referrer_id, 100, 'referral bonus');

  return v_referral_id;
end;
$$;

-- Referral codes policies
create policy "Users can see own referral code"
  on public.referral_codes
  for select
  to authenticated
  using (user_id = auth.uid());

-- Referrals policies
create policy "Users can see referrals they made or received"
  on public.referrals
  for select
  to authenticated
  using (referrer_id = auth.uid() or referee_id = auth.uid());

-- Credits policies
create policy "Users can see own credits"
  on public.credits
  for select
  to authenticated
  using (user_id = auth.uid());

-- Deny all direct modifications (R2) - explicit policies for clarity
-- No insert/update/delete policies on referral_codes, referrals, credits for authenticated
-- Default is deny, but we explicitly revoke to be safe

-- Ensure anon cannot do anything
create policy "Anon cannot see referral codes"
  on public.referral_codes
  for select
  to anon
  using (false);

create policy "Anon cannot see referrals"
  on public.referrals
  for select
  to anon
  using (false);

create policy "Anon cannot see credits"
  on public.credits
  for select
  to anon
  using (false);

-- Revoke direct table modifications from authenticated users
revoke insert, update, delete on public.referral_codes from authenticated;
revoke insert, update, delete on public.referrals from authenticated;
revoke insert, update, delete on public.credits from authenticated;

-- Grant select to authenticated
grant select on public.referral_codes to authenticated;
grant select on public.referrals to authenticated;
grant select on public.credits to authenticated;

-- Grant execute on function to authenticated
grant execute on function public.redeem_referral(text) to authenticated;

-- Grant execute on helper functions (needed for function to work)
grant execute on function public.has_redeemed_referral(uuid) to authenticated;
grant execute on function public.count_referrals_made(uuid) to authenticated;

-- Service role has full access (bypasses RLS by default, but ensure grants)
grant all on public.referral_codes to service_role;
grant all on public.referrals to service_role;
grant all on public.credits to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;
