returns void
language plpgsql
security definer
as $$
declare
  v_record public.records%rowtype;
  v_user_id uuid;
begin
  v_user_id := auth.uid();

  select * into v_record
  from public.records
  where id = p_record_id;

  if not found then
    raise exception 'Record not found';
  end if;

  if not public.is_org_admin(v_record.org_id, v_user_id) then
    raise exception 'Only admins can restore records';
  end if;

  if v_record.deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  if v_record.deleted_at < now() - interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago';
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;

