returns text[]
language plpgsql
stable
as $$
declare
  parts text[];
begin
  parts := string_to_array(name, '/');
  return parts;
end;
$$;

-- Helper function to check if path is in user's folder and is PDF
create or replace function storage.is_user_pdf_object(obj_name text, user_id uuid)
returns boolean
language plpgsql
stable
as $$
declare
  folder_uuid uuid;
  file_name text;
  parts text[];
begin
  parts := string_to_array(obj_name, '/');
  if array_length(parts, 1) < 2 then
    return false;
  end if;

  -- First part should be the user UUID
  begin
    folder_uuid := parts[1]::uuid;
  exception when others then
    return false;
  end;

  -- Check folder matches user
  if folder_uuid != user_id then
    return false;
  end if;

  -- Get filename (last part)
  file_name := parts[array_length(parts, 1)];

  -- Check ends with .pdf
  return file_name like '%.pdf';
end;
