    select count(*)::integer from public.class_spots
    where class_spots.class_id = $1 and class_spots.status = 'enrolled'
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if class has capacity for enrollment
create or replace function public.has_capacity(class_id bigint)
returns boolean as $$
begin
  return (
    select c.capacity > public.enrolled_count(class_id)
    from public.classes c
    where c.id = class_id
  );
end;
$$ language plpgsql security definer;

