-- Helper function: count active permits for a unit
create or replace function public.active_permit_count(p_unit_id bigint)
returns bigint as $$
begin
  return (
    select count(*) from public.permits
    where unit_id = p_unit_id
      and not revoked
      and valid_until >= current_date
  );
end;
$$ language plpgsql security definer;

-- Residents table policies
create policy "residents_select_own"
  on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

