  on public.hoa_admins
  for delete
  to authenticated
  using (false);

-- Permits table policies

-- Select: residents see their unit's permits, admins see all
create policy "permits_select"
  on public.permits
  for select
  to authenticated
  using (
    unit_id = public.current_user_unit_id()
    or public.is_hoa_admin()
  );

-- Insert: residents can add for their unit with constraints
create policy "permits_insert"
  on public.permits
  for insert
  to authenticated
  with check (
    unit_id = public.current_user_unit_id()
    and not public.is_hoa_admin()
    and public.active_permit_count(unit_id) < 2
    and not revoked
    and valid_until <= current_date + interval '365 days'
    and valid_until >= current_date
  );

-- Update: residents can change plate only, admins can revoke only
create policy "permits_update"
  on public.permits
  for update
  to authenticated
  using (
    (unit_id = public.current_user_unit_id() and not public.is_hoa_admin())
    or public.is_hoa_admin()
  )
  with check (
    -- Residents: can only change plate, cannot touch other fields
    (
      unit_id = public.current_user_unit_id()
      and not public.is_hoa_admin()
      and unit_id = public.current_user_unit_id()  -- ensure unit_id unchanged
      and valid_until = (select valid_until from public.permits where id = permits.id)
      and revoked = (select revoked from public.permits where id = permits.id)
      and revoked = false
    )
    or
    -- Admins: can only set revoked to true, cannot change other fields
    (
      public.is_hoa_admin()
      and unit_id = (select unit_id from public.permits where id = permits.id)
      and plate = (select plate from public.permits where id = permits.id)
      and valid_until = (select valid_until from public.permits where id = permits.id)
      and revoked = true
      and (select revoked from public.permits where id = permits.id) = false
    )
  );

-- No delete for anyone
create policy "permits_no_delete"
  on public.permits
  for delete
  to authenticated
  using (false);

