create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
) returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_source_qty integer;
  v_dest_exists boolean;
  v_caller_is_staff boolean;
  v_warehouse_exists boolean;
begin
  -- R4: Check quantity is positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  -- R4: Check destination is not source
  if p_from = p_to then
    raise exception 'Destination cannot be the same as source';
  end if;

  -- R4: Check destination exists
  select exists(select 1 from public.warehouses where id = p_to) into v_warehouse_exists;
  if not v_warehouse_exists then
    raise exception 'Destination warehouse does not exist';
  end if;

  -- R4: Check caller is staff of source warehouse
  select exists(
    select 1 from public.warehouse_staff
    where warehouse_id = p_from and user_id = auth.uid()
  ) into v_caller_is_staff;

  if not v_caller_is_staff then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  -- R4: Check source has enough stock
  select qty into v_source_qty
  from public.stock
  where warehouse_id = p_from and sku = p_sku
  for update;

  if v_source_qty is null or v_source_qty < p_qty then
    raise exception 'Insufficient stock at source warehouse';
  end if;

  -- Perform the transfer
  -- Decrease source
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  -- Increase destination (create if needed)
  select exists(
    select 1 from public.stock where warehouse_id = p_to and sku = p_sku
  ) into v_dest_exists;

  if v_dest_exists then
    update public.stock
    set qty = qty + p_qty
    where warehouse_id = p_to and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return quantity left at source
  return v_source_qty - p_qty;
end;
$$;

-- Grant execute on the function to authenticated users
grant execute on function public.transfer_stock(bigint, bigint, text, integer) to authenticated;

-- Revoke all direct table modifications from authenticated users
-- (they can only use the RPC function which runs as security definer)

-- Ensure warehouse_staff is readable by authenticated (needed for checks, though not explicitly stated in R1, it's implied)
create policy "warehouse_staff_select_self"
  on public.warehouse_staff
  for select
  to authenticated
  using (user_id = auth.uid());

-- Revoke direct modifications on all tables from authenticated
revoke insert, update, delete on public.warehouses from authenticated;
revoke insert, update, delete on public.warehouse_staff from authenticated;
revoke insert, update, delete on public.stock from authenticated;
revoke insert, update, delete on public.transfers from authenticated;

-- Ensure select grants exist
grant select on public.warehouses to authenticated;
grant select on public.warehouse_staff to authenticated;
grant select on public.stock to authenticated;
grant select on public.transfers to authenticated;
