create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_source_qty integer;
  v_result integer;
begin
  -- R4: Validate quantity is positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  -- R4: Validate source and destination are different
  if p_from = p_to then
    raise exception 'Source and destination warehouses must be different';
  end if;

  -- R4: Validate caller is staff of source warehouse
  if not exists (
    select 1 from public.warehouse_staff
    where warehouse_staff.warehouse_id = p_from
      and warehouse_staff.user_id = auth.uid()
  ) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  -- R4: Validate destination exists
  if not exists (
    select 1 from public.warehouses where id = p_to
  ) then
    raise exception 'Destination warehouse does not exist';
  end if;

  -- Lock and check source stock
  select qty into v_source_qty
  from public.stock
  where warehouse_id = p_from and sku = p_sku
  for update;

  -- R4: Validate source has enough stock
  if v_source_qty is null or v_source_qty < p_qty then
    raise exception 'Insufficient stock at source warehouse';
  end if;

  -- Calculate result
  v_result := v_source_qty - p_qty;

  -- Update source stock
  if v_result = 0 then
    delete from public.stock
    where warehouse_id = p_from and sku = p_sku;
  else
    update public.stock
    set qty = v_result
    where warehouse_id = p_from and sku = p_sku;
  end if;

  -- Insert or update destination stock
  insert into public.stock (warehouse_id, sku, qty)
  values (p_to, p_sku, p_qty)
  on conflict (warehouse_id, sku)
  do update set qty = stock.qty + p_qty;

  -- Record transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by, moved_at)
  values (p_from, p_to, p_sku, p_qty, auth.uid(), now());

  return v_result;
end;
$$;

