  if p_user_id = v_caller_id then
    raise exception 'Cannot change your own role';
  end if;

  -- Check target is in the org and get their role
  select role into v_target_current_role
  from public.org_members
  where org_id = p_org_id and user_id = p_user_id;

  v_target_exists := found;

  if not v_target_exists then
    raise exception 'Target user is not a member of this organization';
  end if;

  -- Cannot target an owner
  if v_target_current_role = 'owner' then
    raise exception 'Cannot change the role of an owner';
  end if;

  -- Only allow setting to 'admin' or 'member'
  if p_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member';
  end if;

  -- Update the role
  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end;
$$;

